insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',31,'Contabilidade Geral',null,'João trabalha na Cia X. Seu salário mensal, que é pago no último dia do mês trabalhado, é de R$15.000. Em janeiro de X0, João obteve um adiantamento de R$5.000 com a empresa, para ser descontado do salário de março. Assinale a opção que indica os lançamentos contábeis realizados em 31/03/X0:','{"A": "D- Despesa de salários R$10.000 C- Disponibilidades R$10.000", "B": "D- Despesa de saláriosR$15.000 C- Disponibilidades R$15.000", "C": "D- Despesa de salários R$10.000 D- Adiantamento a empregados R$5.000 C- Disponibilidades R$15.000", "D": "D- Despesa de salários R$15.000 C- Disponibilidades R$10.000 C- Despesa a pagar R$5.000", "E": "D- Despesa de salários R$15.000 C- Disponibilidades R$10.000 C- Adiantamentos a empregados R$5.000"}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',32,'Contabilidade Geral',null,'As despesas com propaganda podem ser contabilizadas, na Demonstração do Resultado do Exercício, como despesas de venda ou como despesas administrativas. Em relação à diferenciação na contabilização, assinale a afirmativa correta.','{"A": "Quando a propaganda é de um produto, será despesa de venda, quando diz respeito a vários produtos, será despesa administrativa.", "B": "Quando a propaganda é vinculada a um exercício social, será despesa de venda, quando a mais de um exercício, será despesa administrativa.", "C": "Quando a propaganda é direcionada a um meio de comunicação, será despesa de venda, quando a vários meios digitais , será despesa administrativa.", "D": "Quando a propaganda é vinculada à promoção de vendas de produtos será despesa de venda, quando representa propaganda institucional, será despesa administrativa.", "E": "Quando a propaganda é realizada após do lançamento do produto, será despesa de venda , quando é realizada antes do lançamento do produto, é despesa administrativa."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',33,'Contabilidade Geral',null,'Na constituição de uma empresa, foi definido que o capital autorizado seria de R$800.000. Deste, foram subscritos R$650.000. Em 31/12/X0, o capital a integralizar era de R$80.000. Assinale a opção que indica o capital social realizado da empresa em 31/12/X0:','{"A": "R$150.000", "B": "R$570.000", "C": "R$650.000", "D": "R$720.000", "E": "R$800.000"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',34,'Contabilidade Geral',null,'Em 01/01/X0, uma sociedade empresária adquiriu, por R$200.000 à vista, uma máquina para utilizar em seus negócios. O frete da máquina foi de R$1.000 e a sua instalação de R$4.000. Na data, foi estimado que a máquina poderia produzir 20.000 unidades do produto “abc”, sendo a produção estimada do seguinte modo: A sociedade empresária inicialmente depreciava os seus ativos imobilizados pelo método dos benefícios gerados. Em 01/01/X3, os contadores da sociedade empresária julgaram que seria mais adequado depreciar os seus ativos imobilizados de acordo com o método da linha reta. Na data, foi estimado que a máquina poderia ser utilizada por mais 5 anos a partir desta data, sendo o valor residual zero. Assinale a opção que indica a depreciação acumulada da máquina em 31/12/X4.','{"A": "R$164.000.", "B": "R$166.100.", "C": "R$168.100.", "D": "R$190.000.", "E": "R$194.750. Ano Produção X0 2.000 X1 4.000 X2 8.000 X3 3.000 X4 2.000 X5 1.000"}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',35,'Contabilidade Geral',null,'De acordo com a Lei nº 6.404/1976 e modificações, o saldo das reservas de lucros, exceto as para contingências, de incentivos fiscais e de lucros a realizar, não poderá ultrapassar o capital social. Atingindo esse limite, a assembleia deverá deliberar sobre a aplicação do excesso. A aplicação poderá ser feita','{"A": "na liquidação de passivos ou na compra de ativos.", "B": "no aumento do capital social ou na compra de ações em tesouraria.", "C": "na constituição de reservas de lucros para expansão ou na compra de ações em tesouraria.", "D": "na constituição de reservas de lucros para expansão ou na distribuição de dividendos.", "E": "no aumento do capital social ou na distribuição de dividendos."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',36,'Contabilidade Geral',null,'Em 01/01/X0, uma editora brasileira adquiriu os direitos autorais de uma coleção de livros franceses por R$300.000. O contrato tinha vigência de 5 anos a partir de 01/07/X0, quando o primeiro livro ficou pronto para ser lançado. A editora contratou um profissional para traduzir o primeiro livro; ele recebeu R$30.000 pelo serviço. Além disso, a editora organizou uma festa de lançamento do livro, na qual foram gastos R$20.000. A editora amortiza os seus contratos de direitos autorais de acordo com o método da linha reta. Assinale a opção que indica a despesa de amortização dos direitos autorais do livro em 31/12/X0.','{"A": "R$30.000.", "B": "R$33.000.", "C": "R$60.000.", "D": "R$66.000.", "E": "R$70.000."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',37,'Contabilidade Geral',null,'A Cia. Azul possui 85% de participação na Cia. Branca, contabilizando o investimento pelo método da equivalência patrimonial. Em 31/12/X0, a Cia. Branca distribuiu à Cia Azul dividendos no valor de R$40.000. Assinale a opção que indica a contabilização dos dividendos recebidos nas demonstrações contábeis da Cia. Azul em 31/12/X0, em contrapartida ao aumento de caixa.','{"A": "Aumento no Passivo.", "B": "Redução em Investimentos.", "C": "Aumento em Investimentos.", "D": "Aumento em Patrimônio Líquido.", "E": "Redução no Patrimônio Líquido."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',38,'Contabilidade Geral',null,'Com o intuito de aumentar o seu saldo em caixa, uma sociedade empresária emitiu, em 01/01/X0, ações, captando R$150.000 e debêntures, captando R$80.000. Assinale a opção que indica a contabilização do aumento em caixa e equivalentes de caixa, ocasionado pelas duas emissões, na Demonstração dos Fluxos de Caixa da sociedade empresária no ano de X0.','{"A": "Fluxo de caixa gerado pela atividade operacional: R$230.000.", "B": "Fluxo gerado pela atividade de investimentos: R$230.000.", "C": "Fluxo de caixa gerado pela atividade de financiamento: R$230.000.", "D": "Fluxo de caixa gerado pela atividade de investimento: R$150.000 e pela atividade operacional: R$80.000.", "E": "Fluxo de caixa gerado pela atividade de financiamento: R$150.000 e pela atividade de investimento: R$80.000."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',39,'Contabilidade Geral',null,'Uma entidade possui contas bancárias em três diferentes instituições. Em 31/12/X0, os saldos eram os seguintes: Assinale a opção que indica a contabilização da conta no banco Gama no balanço patrimonial da entidade.','{"A": "Passivo circulante.", "B": "Ativo circulante.", "C": "Redutora do ativo circulante.", "D": "Ativo realizável a longo prazo.", "E": "Redutora do ativo realizável a longo prazo. Banco Saldo da conta Alfa R$ 20.000 Beta R$ 18.000 Gama -R$ 10.000"}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',40,'Contabilidade Geral',null,'Em 31/12/X0, as Cias X e Y apresentavam os seguintes balanços patrimoniais: Em 01/01/X1, a Cia X adquiriu 100% de participação na Cia Y por R$35.000 à vista. Na data, a empresa estimou, em relação aos ativos e passivos da Cia Y, que:  O terreno tinha valor justo de R$23.000  A marca tinha valor justo de R$8.000  Os financiamentos tinham valor de mercado de R$10.000. Em relação ao balanço patrimonial consolidado após a aquisição, analise as afirmativas a seguir: I. O ativo circulante é de R$120.000. II. O ativo imobilizado é de R$23.000. III. O ativo intangível é de R$8.000. IV. O passivo não circulante é de R$10.000 V. O patrimônio líquido é de R$102.000. Está correto o que se afirma em','{"A": "I, III e IV, apenas.", "B": "II, IV e V, apenas.", "C": "II, III e IV, apenas.", "D": "I, II, IV e V, apenas.", "E": "II, III, IV e V, apenas."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',41,'Contabilidade Geral',null,'De acordo com a Lei nº 6.404/1976 e modificações, as operações de incorporação, fusão e cisão serão submetidas à deliberação da assembleia-geral das companhias interessadas mediante explicação, na qual serão expostos os pontos a seguir, à exceção de um. Assinale-o.','{"A": "O efeito estimado nas cotações futuras das ações na bolsa de valores.", "B": "Os motivos ou fins da operação e o interesse da companhia na sua realização.", "C": "O valor de reembolso das ações a que terão direito os acionistas dissidentes.", "D": "As ações que os acionistas preferenciais receberão e as razões para a modificação dos seus direitos, se prevista.", "E": "A composição, após a operação, segundo espécies e classes das ações, do capital das companhias que deverão emitir ações em substituição às que se deverão extinguir."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',42,'Contabilidade Geral',null,'A incorporação, fusão ou cisão da companhia emissora de debêntures em circulação dependerá da prévia aprovação dos debenturistas, reunidos em assembleia especialmente convocada com esse fim. Se for assegurado aos debenturistas que o desejarem, durante o prazo mínimo de 6 meses a contar da data da publicação das atas das assembleias relativas à operação, o resgate das debêntures de que forem titulares','{"A": "a aprovação pela assembleia será dispensada.", "B": "a incorporação, fusão ou cisão será antecipada.", "C": "uma auditoria de caráter especial será realizada.", "D": "uma demonstração financeira intermediária deverá ser publicada.", "E": "a avaliação da debênture será baseada na forma, em detrimento à essência."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',43,'Contabilidade Pública',null,'De acordo com a Lei nº 4.320/64, as receitas podem ser classificadas em correntes e de capital. Assinale a opção que contém exemplos de receita classificadas, respectivamente, como corrente e como de capital.','{"A": "Tributária e industrial.", "B": "Industrial e de serviços.", "C": "De serviços e tributária.", "D": "Patrimonial e alienação de bens.", "E": "Amortização de empréstimos e agropecuária."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',44,'Contabilidade Pública',null,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP), as características qualitativas são atributos que tornam a informação útil para os usuários e dão suporte ao cumprimento dos objetivos da informação contábil. Em relação às características qualitativas, assinale a afirmativa correta.','{"A": "A representação fidedigna é a qualidade da informação que permite que os usuários compreendam o seu significado.", "B": "A comparabilidade é a qualidade da informação que possibilita aos usuários identificar semelhanças e diferenças entre dois conjuntos de fenômenos.", "C": "A tempestividade é a qualidade da informação que influencia significativamente o cumprimento dos objetivos da elaboração e da divulgação da informação contábil.", "D": "A relevância é a qualidade da informação que aprimora a sua utilidade como insumo para processos de avaliação da prestação de contas e responsabilização e a sua capacidade de informar os processos decisórios.", "E": "A compreensibilidade é a qualidade da informação que ajuda a assegurar aos usuários que a informação contida nas demonstrações contábeis representa fielmente os fenômenos econômicos ou de outra natureza que se propõe a representar. Cia X Cia Y Ativo Circulante Disponibilidades 80.000 10.000 Estoques 30.000 Ativo não Circulante Imobilizado Terrenos 20.000 Total do Ativo 110.000 30.000 Passivo Circulante Salários a pagar 8.000 Passivo não Circulante Financiamentos 12.000 Patrimônio Líquido Capital Social 102.000 18.000 Passivo + PL 110.000 30.000"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',45,'Direito Administrativo',null,'O leilão representa uma modalidade de licitação. Ele será precedido da divulgação do edital em sítio eletrônico oficial, que conterá os aspectos a seguir, à exceção de um. Assinale-o.','{"A": "A indicação do lugar onde estão os móveis, os veículos e os semoventes.", "B": "A especificação de eventuais ônus, gravames ou pendências existentes sobre os bens a serem leiloados.", "C": "A denominação dos antigos proprietários dos bens e o motivo pelo qual os mesmos estão sendo leiloados.", "D": "A descrição do bem, com suas características, e, no caso de imóvel, sua situação e suas divisas, com remissão à matrícula e aos registros.", "E": "O valor pelo qual o bem foi avaliado, o preço mínimo pelo qual poderá ser alienado, as condições de pagamento e, se for o caso, a comissão do leiloeiro designado."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',46,'Contabilidade de Custos',null,'Em relação à diferenciação entre os custos e as despesas em uma empresa industrial, assinale a afirmativa correta.','{"A": "Os custos representam gastos, enquanto as despesas são desembolsos.", "B": "Os custos representam o evento econômico, enquanto as despesas o evento financeiro.", "C": "Os custos são considerados investimentos, enquanto as despesas são consideradas perdas.", "D": "Os custos relacionam-se ao processo produtivo, enquanto as despesas estão principalmente relacionadas com as áreas comercial e administrativa.", "E": "Os custos são contabilizados de acordo com ao regime de competência, enquanto as despesas com o regime de caixa."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',47,'Contabilidade de Custos',null,'Uma entidade utiliza o custeio por absorção. A entidade incorre nos seguintes custos e despesas em seu processo operacional: custos diretos, custos indiretos e despesas de vendas. De acordo com o método do custeio por absorção, são alocados aos produtos','{"A": "os custos diretos, apenas.", "B": "os custos indiretos, apenas.", "C": "os custos diretos e indiretos, apenas.", "D": "os custos diretos e as despesas de vendas, apenas.", "E": "os custos diretos, os custos indiretos e as despesas de vendas."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',48,'Auditoria',null,'De acordo com a NBC TI 01 – Da Auditoria Interna, o processo de obtenção e avaliação das informações compreende a obtenção de informações sobre os assuntos relacionados aos objetivos e ao alcance da Auditoria Interna. Nesse sentido, a informação adequada é aquela que, sendo confiável,','{"A": "é factual, convincente e suficiente.", "B": "auxilia a entidade a atingir suas metas, no menor espaço de tempo possível.", "C": "fornece suporte às conclusões e às recomendações da Auditoria Interna.", "D": "torna possível que uma pessoa prudente e informada tire conclusões da mesma forma como o auditor interno.", "E": "propicia a melhor evidência alcançável, por meio do uso apropriado das técnicas de Auditoria Interna."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',49,'Auditoria',null,'De acordo com a NBC TA 200 (R1) – Objetivos Gerais do Auditor Independente e a Condução da Auditoria em Conformidade com Normas de Auditoria, quando o trabalho de auditoria é de interesse público e, portanto, exigido pelo Código de Ética Profissional do Contabilista e pelas normas profissionais do CFC, exige-se que o auditor seja independente da entidade sujeita a auditoria. A independência do auditor frente à entidade caracteriza-se principalmente por','{"A": "tornar os resultados do trabalho do auditor mais ágeis e objetivos.", "B": "possibilitar que o auditor detecte ocorrências de fraude e de erro com mais precisão.", "C": "aprimorar a capacidade do auditor de atuar com maior rigor, consistência e transparência.", "D": "salvaguardar a capacidade do auditor de formar opinião de auditoria sem ser afetado por influências que poderiam comprometer essa opinião.", "E": "proporcionar um relatório do auditor mais próximo da realidade, onde a essência econômica é levada em consideração, em detrimento à forma jurídica."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',50,'Auditoria',null,'De acordo com a NBC TA 300 (R1) – Planejamento da Auditoria de Demonstrações Contábeis, o planejamento da auditoria envolve a definição de estratégia global para o trabalho e o desenvolvimento de plano de auditoria. A responsabilidade sobre o plano de auditoria é','{"A": "da administração da entidade, que deve explicar os elementos do planejamento ao auditor, de forma a melhorar a qualidade dos resultados obtidos.", "B": "do auditor e da administração da entidade que, no entanto, devem evitar discutir os elementos do planejamento, de modo a não comprometer a independência.", "C": "do auditor e da administração da entidade, que devem discutir os elementos do planejamento, de forma a melhorar a qualidade dos resultados obtidos.", "D": "do auditor, que deve abster-se de discutir os elementos do planejamento com a administração da entidade, de modo a não comprometer a eficácia dessa auditoria.", "E": "do auditor, que pode optar por discutir os elementos do planejamento com a administração da entidade, de forma a facilitar a condução e o gerenciamento do trabalho de auditoria."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',51,'Contabilidade Geral',null,'Um marco para a evolução da Contabilidade foi o processo de convergência das normas contábeis às normas internacionais. Em relação às consequências ao processo de convergência das normas contábeis, avalie se as afirmativas a seguir são falsas (F) ou verdadeiras (V): ( ) Aumento do custo do capital que deriva da processo. ( ) Redução de riscos nos investimentos internacionais, sob a forma de empréstimo financeiro ou sob a forma de participação societária. ( ) Maior facilidade de comunicação internacional no mundo dos negócios com o uso de uma linguagem contábil mais homogênea. As afirmativas são, respectivamente,','{"A": "V – V – V.", "B": "V – V – F.", "C": "V – F – V.", "D": "F – V – V.", "E": "F – F – V."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',52,'Contabilidade Geral',null,'De acordo com a NBC TG Estrutura Conceitual- Estrutura Conceitual para Relatório Financeiro, os investidores, credores por empréstimos e outros credores, existentes e potenciais, representam os principais usuários aos quais se destinam os relatórios financeiros para fins gerais. De acordo com a norma, a administração da entidade que reporta não é considerada usuário primário, uma vez que','{"A": "pode obter internamente as informações financeiras de que precisa.", "B": "é a responsável direta pela elaboração destes relatórios financeiros.", "C": "tem necessidades de informação diferentes e possivelmente conflitantes em relação aos demais usuários.", "D": "sua necessidade é mais restrita e específica, enquanto os relatórios financeiros são mais abrangentes.", "E": "trabalha com representações exatas, enquanto os relatórios financeiros baseiam-se em estimativas, julgamentos e modelos."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',53,'Contabilidade Geral',null,'De acordo com a NBC TG Estrutura Conceitual- Estrutura Conceitual para Relatório Financeiro, ativo é um direito que tem o potencial de produzir benefícios econômicos, presente e controlado pela entidade, como resultado de eventos passados. As opções a seguir indicam exemplos de direitos que representam ativos reconhecidos pela Contabilidade e que correspondem à obrigação de outra parte, à exceção de uma. Assinale-a.','{"A": "Direitos de receber caixa.", "B": "Direitos de receber produtos ou serviços.", "C": "Direitos de influenciar a tomada de decisões estratégicas.", "D": "Direitos de trocar recursos econômicos com outra parte em condições favoráveis.", "E": "Direitos de beneficiar-se de obrigação de outra parte para transferir um recurso econômico se ocorrer evento futuro incerto especificado."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',54,'Ética Profissional',null,'De acordo com o Decreto-Lei nº 9.295/46, representam atribuições do Conselho Federal de Contabilidade','{"A": "expedir e registrar a carteira profissional do profissional contabilista.", "B": "regular acerca dos princípios contábeis, do Exame de Suficiência, do cadastro de qualificação técnica e dos programas de educação continuada.", "C": "estudar, preparar e emitir, de modo exclusivo, os pronunciamentos técnicos sobre procedimentos de Contabilidade, visando à centralização e uniformização do seu processo de produção.", "D": "examinar reclamações a representações escritas acerca dos serviços de registro e das infrações dos dispositivos legais vigentes, relativos ao exercício da profissão de contabilista.", "E": "fiscalizar o exercício das profissões de contador, impedindo e punindo as infrações, e enviando às autoridades competentes relatórios sobre fatos que apurarem, e cuja solução ou repressão não seja de sua aIçada."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',55,'Ética Profissional',null,'De acordo com a NBC PG 01 – Código de Ética Profissional do Contador, o contador pode','{"A": "assinar documentos ou peças contábeis elaborados por outro profissional alheio à sua orientação, supervisão ou revisão.", "B": "transferir, parcialmente, a execução dos serviços a seu cargo a outro profissional, transferindo para este a responsabilidade técnica.", "C": "publicar, em seu nome, trabalho científico ou técnico do qual não tenha participado, mas que são úteis à comunidade contábil.", "D": "transferir o contrato de serviços a seu cargo a outro profissional, que achar mais capacitado, mesmo sem a anuência do cliente.", "E": "indicar, em qualquer modalidade ou veículo de comunicação, títulos, especializações, serviços oferecidos, trabalhos realizados e, quando autorizada, a relação de clientes."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',56,'Matemática Financeira',null,'A fim de antecipar fluxo de caixa, uma empresa comercial privada descontou uma duplicata de R$ 60.000,00 junto a uma instituição financeira. Nessa operação, após descontados os juros, o IOF devido e a taxa de administração de R$ 80,00, a empresa recebeu R$ 52.000,00 líquidos. A instituição financeira desconta duplicatas a juros simples de 1,8% ao mês. O IOF é cobrado por meio de duas alíquotas que incidem sobre o valor da duplicata: I. a primeira, fixada em 0,38%; II. a segunda, de 0,0041% ao dia. Considerando-se o mês comercial, conclui-se que a duplicata foi descontada com um prazo de antecedência','{"A": "menor do que 120 dias.", "B": "maior do que 120 dias e menor do que 150 dias.", "C": "maior do que 150 dias e menor do que 180 dias.", "D": "maior do que 180 dias e menor do que 210 dias.", "E": "maior do que 210 dias."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',57,'Matemática Financeira',null,'Um empréstimo foi concedido para ser quitado em 4 prestações mensais, iguais e consecutivas no valor de R$ 6.615,00, sendo a primeira delas paga um mês após a contratação do empréstimo. Entretanto, esse primeiro pagamento não foi efetuado na data prevista. Na data do pagamento da 2ª prestação, o devedor decide quitar toda a sua dívida, pagando os atrasados, a prestação vigente e trazendo os pagamentos futuros a valor presente. Os juros contratados são de 5% ao mês e o credor cobra, em caso de atraso, apenas multa moratória fixa de 2% sobre o valor atrasado. Para quitar a sua dívida, o devedor precisará pagar','{"A": "R$ 25.662,30.", "B": "R$ 25.860,75.", "C": "R$ 25.993,05.", "D": "R$ 26.000,00.", "E": "R$ 26.042,05."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',58,'Matemática Financeira',null,'Uma aplicação sofre capitalização composta diariamente. Após 60 dias, o rendimento dessa aplicação foi de 0,54% a.m. Considerando o mês comercial, a taxa mensal efetiva dessa operação foi','{"A": "1,0001830 – 1", "B": "1,0001860 – 1", "C": "1,0000930 – 1", "D": "1,0000960 – 1", "E": "0,0054"}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',59,'Matemática Financeira',null,'Um capital de R$ 32.400,00 é aplicado à taxa composta de 20% ao ano, durante dois anos e três meses. Se esse valor fosse submetido à convenção linear, o montante final seria, com relação ao montante obtido na aplicação original, [Dado: 1,202,25 = 1,507]','{"A": "R$ 1.620,00 maior.", "B": "R$ 324,00 menor.", "C": "R$ 324,00 maior.", "D": "R$ 162,00 menor.", "E": "R$ 162,00 maior."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Técnico de Gestão Administrativa – Contador',2023,null,'Tipo 1',60,'Matemática Financeira',null,'Considere o seguinte fluxo de caixa de um projeto de investimento. Anos 0 1 2 3 4 R$ (230.000) P 64.480 P 74.880 Esse projeto apresenta Taxa Interna de Retorno de 20% ao ano. Os rendimentos esperados P ao final do primeiro e do terceiro anos de investimento são idênticos. O valor de P está entre','{"A": "R$ 104.000,00 e R$ 105.000,00.", "B": "R$ 105.000,00 e R$ 106.000,00.", "C": "R$ 106.000,00 e R$ 107.000,00.", "D": "R$ 107.000,00 e R$ 108.000,00.", "E": "R$ 108.000,00 e R$ 109.000,00."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns112-tecnico-de-gestao-administrativa-contadorcns112-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno')
insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',1,'Língua Portuguesa',null,'Observe o texto a seguir. À Beça Gumercindo Bessa (1859-1913), jornalista e jurista alagoano, foi adversário de Rui Barbosa na Questão Acreana, em que o Estado do Amazonas pretendia incorporar o Território do Acre. Bessa venceu a questão em favor do Acre, apresentando argumentos irrefutáveis e numa quantidade impressionante. Posteriormente, mas não muito, Rodrigues Alves (Presidente do Brasil de 1902 a 1906) diria a um cidadão que lhe apresentava um pedido com justificativas infindáveis: “O senhor tem argumentos à Bessa”. A partir daí, popularizou-se a expressão à beça com o sentido de uma grande quantidade ou intensidade. Por que os dois esses viraram cê-cedilha? Ninguém sabe. (Reinaldo Pimenta, A Casa da Mãe Joana 2) A ideia central do texto é a de','{"A": "explicar a origem histórica de uma expressão popular.", "B": "justificar a duplicidade de grafia de uma expressão.", "C": "indicar o sentido preciso da expressão à beça.", "D": "mostrar como as palavras se constroem socialmente.", "E": "documentar um erro ortográfico."}'::jsonb,'A',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',2,'Língua Portuguesa',null,'Assinale a frase em que o segmento sublinhado foi substituído de forma conveniente por um particípio.','{"A": "Qualquer pessoa que não tem senso de humor está à mercê de todos / desprovida de.", "B": "Os empresários que não têm dinheiro, recorrem aos empréstimos bancários / encarecidos de.", "C": "Os empregados que não têm iniciativa não recebem promoções / inativos.", "D": "Os clientes que não têm possibilidades de locomoção, sobem pelas escadas rolantes / impossíveis.", "E": "Aquele que não tem motivo para pedir ajuda, deve ficar quieto / desmotivado."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',3,'Língua Portuguesa',null,'Assinale a frase em que a utilização do acento grave indicativo da crase é realizada de forma errada.','{"A": "Seis horas de sono, seis horas no estudo das leis, quatro passadas em oração, as restantes dedicadas à natureza.", "B": "As datas, só elas dão verdadeira consistência à vida e à sorte.", "C": "O futuro é algo que todos nós atingimos à velocidade de sessenta minutos por hora.", "D": "À medida que tenho menos tempo para praticar as coisas, menos curiosidade tenho por aprendê-las.", "E": "O futuro não pertence à ninguém. Não há precursores, apenas há atrasados."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',4,'Língua Portuguesa',null,'Em todas as frases abaixo aparece a conjunção e sublinhada. Assinale a frase em que ela é empregada com valor adversativo.','{"A": "Vida: um espaço de tempo cuja primeira metade é arruinada por nossos pais e a segunda metade, por nossos filhos.", "B": "Uma casa é feita de tijolo e pedra. Um lar é feito apenas de amor.", "C": "Esculpir: eu escolho um bloco de mármore e retiro tudo o que não preciso.", "D": "Arte é fazer alguma coisa do nada e vendê-la.", "E": "Nada tenho a dizer e estou dizendo-o. Tal é a poesia."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',5,'Língua Portuguesa',null,'A maioria das palavras mostra vários significados (polissemia), o que também ocorre com as preposições. Indique a frase em que a preposição PARA tem seu significado corretamente indicado.','{"A": "Meu sonho é ir para a Europa / finalidade.", "B": "Saiu para comprar roupas de frio / direção.", "C": "Estava para sair quando chegaram as visitas / proximidade.", "D": "O ônibus era para cinquenta passageiros / interesse.", "E": "Para os pássaros, o canto faz parte da vida / destinação."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',6,'Língua Portuguesa',null,'Observe o trecho seguinte: “A compra desses livros, mesmo que estejamos num país sem inflação exagerada, nos ensina a valorizar nosso dinheiro, só o empregando em necessidades reais.” A locução sublinhada poderia ser substituída, sem prejuízo do sentido, por','{"A": "visto que.", "B": "além do que.", "C": "desde que.", "D": "ainda que.", "E": "mais do que."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',7,'Língua Portuguesa',null,'Assinale a frase em que o vocábulo sublinhado pertence à classe dos adjetivos.','{"A": "Os velhos amigos estão sempre conosco.", "B": "Aconselhe seu amigo quando for necessário.", "C": "Devemos sempre homenagear um amigo.", "D": "Em nossa família, um é amigo do outro.", "E": "Nenhuma pessoa possui muitos amigos."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',8,'Língua Portuguesa',null,'Assinale a frase em que é optativo o emprego do artigo sublinhado.','{"A": "Engenheiros são as únicas pessoas que não podem ignorar a Matemática.", "B": "Uma coisa urgente a fazer é prender todos os corruptos.", "C": "Nunca diga mentiras para os seus pais.", "D": "O Brasil é o maior país da América do Sul.", "E": "É necessário acabar com a inflação neste país."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',10,'Língua Portuguesa',null,'Assinale a frase em que os termos sublinhados não mostram, em caso de troca de posição dos termos, mudança de significado.','{"A": "Marinheiro valente.", "B": "Bom homem.", "C": "Grande sujeito.", "D": "Pobre professor.", "E": "Simples funcionário."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',11,'Língua Portuguesa',null,'Os adjetivos podem indicar qualidades positivas ou negativas, características, estados ou relações dos substantivos. Assinale a frase em que o adjetivo destacado indica uma característica.','{"A": "Esse é um mundo pequeno, mas eu não queria ter que pintá- lo.", "B": "As pessoas, como os metais, têm apenas uma superfície brilhante.", "C": "A Terra é mais nobre que o mundo que colocamos sobre ela.", "D": "O mundo pode ser um palco, mas o elenco é um horror.", "E": "Para este mundo ficar bom, é preciso fazer outro."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',12,'Língua Portuguesa',null,'Em muitos adjetivos pátrios compostos, o primeiro termo mostra uma forma alatinada e reduzida. Assinale a opção em que o adjetivo citado corresponde corretamente aos países indicados.','{"A": "anglo-germânico (Irlanda e Alemanha).", "B": "austro-inglês (Austrália e Inglaterra).", "C": "euro-americano (Europa e América).", "D": "teuto-nipônico (Filipinas e Japão).", "E": "sino-hispânico (Japão e Espanha)"}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',13,'Língua Portuguesa',null,'Observe a seguinte frase: “Consta que o mundo muda constantemente e, na Natureza, ser constante seria uma inconstância”. Nessa frase foram sublinhadas quatro palavras da mesma família, mas de classes gramaticais diferentes. Assinale a opção em que foram indicadas, na mesma ordem de classes, quatro palavras da mesma família.','{"A": "estudar / estudantemente / estudado / estudo.", "B": "entreter / entretidamente / entretido / entretenimento.", "C": "convir / convenientemente / convencido / convenção.", "D": "prever / previamente / provisto / prevenção.", "E": "divertir / divertidamente / divertido / diversificação."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',14,'Língua Portuguesa',null,'Na frase “Ninguém ousa dizer adeus aos próprios hábitos. Muitos suicidas se detiveram no limiar da morte ao pensar no café onde vão jogar todas as noites sua partida de dominó” há um pronome possessivo sublinhado, cujo valor é o de','{"A": "indefinição.", "B": "designação de um hábito.", "C": "de deferência e respeito.", "D": "aproximação numérica.", "E": "propriedade material."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',15,'Língua Portuguesa',null,'Em todas as frases abaixo está sublinhado o advérbio “não” ou “nunca”; todas essas frases foram reescritas de forma a eliminar esses advérbios, mas conservando o sentido original. Assinale a frase em que essa modificação foi feita de forma inadequada.','{"A": "Não há nada de tão absurdo que o hábito não torne aceitável / Nada há de tão absurdo que o hábito não torne aceitável.", "B": "Não existe nada mais forte que o hábito / Nada é mais forte que o hábito.", "C": "As mudanças nunca ocorrem sem inconvenientes / As mudanças sempre ocorrem com inconvenientes.", "D": "A coragem é filha da prudência, não da temeridade / A coragem é filha da prudência, mas sim da temeridade.", "E": "E amanhã não seremos o que fomos nem o que somos / E amanhã seremos diferentes do que fomos e do que somos."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',16,'Língua Portuguesa',null,'As opções a seguir apresentam orações subordinadas adverbiais. Assinale aquela em que a classificação dada está correta.','{"A": "Se eu fosse rei, instituiria cátedras para ensinar a calar / oração comparativa.", "B": "Quando se tem tudo para temer, não se deve temer nada / oração condicional.", "C": "Não há nada de tão absurdo que o hábito não torne aceitável / oração consecutiva.", "D": "Algumas pessoas foram consideradas corajosas porque tinham medo de fugir / final.", "E": "Dai-me força e coragem para contemplar meu interior / concessiva."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',17,'Língua Portuguesa',null,'Assinale a frase em que o adjetivo sublinhado mostra uma função sintática diferente da que mostra nas demais frases.','{"A": "O hábito torna suportáveis até as coisas assustadoras.", "B": "O silêncio deles é uma eloquente afirmação.", "C": "O silêncio tornou-se sua linguagem materna.", "D": "Os bons homens são extremamente raros.", "E": "A sabedoria humana ensina muito se ensina a calar."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',18,'Língua Portuguesa',null,'Algumas vezes ocorrem duas palavras idênticas na grafia, mas diferentes na acentuação tônica como, por exemplo, crédito e credito (do verbo creditar). As palavras sublinhadas nas frases abaixo são idênticas graficamente a outras palavras, mas com acentuação tônica diferente e diferente significado. Assinale a frase cuja palavra sublinhada mostra outra acentuação, mas com o mesmo significado.','{"A": "O hábito é o grande guia da vida humana.", "B": "Ninguém ousa dizer adeus aos próprios hábitos. Muitos suicidas se detiveram no limiar da morte ao pensar no café onde vão jogar todas as noites sua partida de dominó.", "C": "Toda palavra pronunciada suscita seu sentido contrário.", "D": "É magnífico ouvir o silêncio daquele homem.", "E": "Os hieróglifos já são compreendidos pelos estudiosos."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',19,'Língua Portuguesa',null,'As preposições em língua portuguesa podem ser nocionais, quando colaboram semanticamente com a frase, e gramaticais, quando são exigidas pela regência de algum termo anterior. Assinale a frase em que a preposição sublinhada mostra valor gramatical.','{"A": "A verdadeira glória de um vencedor é a de ser clemente.", "B": "A frase é a toalete do espírito.", "C": "As mulheres não sabem o que dizer no fim de um amor.", "D": "O hábito é o grande guia da vida humana.", "E": "Os fatos devem provar a bondade das palavras."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',20,'Língua Portuguesa',null,'As opções a seguir apresentam um adjetivo sublinhado. Assinale aquela em que esse adjetivo foi substituído por uma oração adjetiva adequada.','{"A": "Ouso afirmar que são os homens, e não as mulheres, os culpados pela maioria dos casamentos infelizes / que denunciam a culpa do parceiro.", "B": "Temam menos a morte e mais a vida insuficiente / que não é bastante.", "C": "O hábito torna suportáveis até as coisas assustadoras / que levam susto.", "D": "O casamento, se queres saber a verdade, é um mal, mas um mal necessário / de que se prescinde.", "E": "Ser marido é um trabalho de tempo integral / que é diariamente íntegro. Informática"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',21,'Informática',null,'Os monitores de vídeo podem ter diferentes resoluções de exibição. Assinale a resolução que corresponde, em pixels, à de vídeo 4K (UHD).','{"A": "1280 x 1080", "B": "1280 x 720", "C": "1920 x 1080", "D": "3840 x 2160", "E": "7680 x 4320"}'::jsonb,'D',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',22,'Informática',null,'Francisco estava utilizando o Explorador de Arquivos no Windows quando, inadvertidamente, excluiu um arquivo. Assinale a combinação de teclas que Francisco pode usar imediatamente para recuperar o arquivo.','{"A": "Ctrl+V", "B": "Alt+F4", "C": "Ctrl+C", "D": "Ctrl+X", "E": "Ctrl+Z"}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',23,'Informática',null,'João está editando um documento, no Word, composto por três segmentos: uma introdução de apresentação, um índice completo sobre os tópicos abordados e o corpo do documento. Em cada um desses segmentos, a numeração de páginas deve ser reiniciada a partir de 1. O recurso do MS Word que viabiliza e torna bem mais simples esse tipo de edição é','{"A": "a inserção de símbolos especiais.", "B": "o uso de cabeçalhos dinâmicos.", "C": "o uso de quebras de página.", "D": "o uso de quebras de seções.", "E": "o uso de rodapés dinâmicos."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',24,'Informática',null,'Analise as afirmativas a seguir, a respeito do uso de colunas no corpo de documentos criados no MS Word. I. O número de colunas não pode passar de 5. II. As colunas podem ser de larguras diferentes. III. Não é permitida a inserção de quebra de página no interior de uma coluna. Somente está correto o que se afirma em','{"A": "I.", "B": "II.", "C": "III.", "D": "I e II.", "E": "II e III."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',25,'Informática',null,'Maria recebeu um arquivo, intitulado “casa.jpg”, a ser incluído no texto do documento Word que ela está preparando. Assinale a opção da guia Inserir que Maria deve utilizar para fazer essa inserção.','{"A": "Formas.", "B": "Gráfico.", "C": "Imagens.", "D": "Instantâneo.", "E": "SmartArt. Legislação"}'::jsonb,'C',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',26,'Processo Legislativo',null,'Acerca da atuação dos órgãos da Assembleia Legislativa do Estado do Maranhão, à luz do texto de seu Regimento Interno, analise as seguintes atividades: I. Estabelecer diretrizes para divulgação das atividades da Assembleia. II. Interpretar e fazer observar o ordenamento jurídico de pessoal e dos serviços administrativos da Assembleia. III. Convidar o Deputado a retirar-se do recinto do Plenário, quando perturbar a ordem. IV. Receber, examinar e encaminhar aos órgãos competentes as reclamações ou representações de pessoas físicas ou jurídicas sobre violação ou qualquer forma de discriminação atentatória dos direitos e liberdades fundamentais. As referidas atividades, ainda que por meio das pessoas que os compõem, são de atribuição, respectivamente, dos seguintes órgãos:','{"A": "I – Secretaria; II – Corregedoria Parlamentar; III – Mesa; IV – Presidência.", "B": "I – Presidência; II – Mesa; III – Corregedoria Parlamentar; IV – Secretaria.", "C": "I – Presidência; II – Secretaria; III – Ouvidoria Parlamentar; IV – Mesa.", "D": "I – Mesa; II – Secretaria; III – Presidência; IV – Ouvidoria Parlamentar.", "E": "I – Secretaria; II – Mesa; III – Corregedoria Parlamentar; IV – Ouvidoria Parlamentar."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',27,'Processo Legislativo',null,'O procedimento de votação é aquele por meio do qual os Deputados estaduais deliberam sobre projetos de lei e de resolução, bem como as demais proposições de competência da Casa Legislativa. Sobre a votação na Assembleia Legislativa do Estado do Maranhão, de acordo com seu Regimento Interno, assinale a afirmativa correta.','{"A": "Quando, no curso de uma votação, se esgotar o tempo próprio da sessão, a votação ficará automaticamente prorrogada para a próxima sessão seguinte.", "B": "Em regra, as proposições serão votadas individualmente, podendo, por deliberação específica, excepcionalmente serem votadas em globo.", "C": "Em regra, dependerá de aprovação do Plenário o requerimento de destaque apresentado por bancada de Partido ou Bloco.", "D": "Pelo processo simbólico de votação, o Presidente, ao anunciar a votação de qualquer matéria, convidará os Deputados a favor para ficarem de pé, e proclamará o resultado manifesto dos votos, anunciando sempre os nomes dos Deputados que votaram contra.", "E": "A matéria não poderá ser colocada em votação se o Deputado autor da proposição estiver ausente de Plenário, salvo após sua inclusão na Ordem do Dia por duas sessões ordinárias consecutivas."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',28,'Processo Legislativo',null,'Um Secretário Estadual foi convocado a ser ouvido pela Assembleia Legislativa do Estado do Maranhão (ALEMA). No dia e hora em que comparecer perante a ALEMA, nos termos do Regimento Interno, a sessão para sua oitiva deverá ser uma sessão','{"A": "especial.", "B": "extraordinária.", "C": "ordinária.", "D": "solene.", "E": "preparatória."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',29,'Processo Legislativo',null,'Quando finda uma legislatura, a regra geral é a de que serão arquivadas todas as proposições. Porém, o Regimento Interno da Assembleia Legislativa do Estado do Maranhão prevê algumas exceções a essa regra. Assinale a opção que configura uma exceção à regra geral de arquivamento ao fim da legislatura.','{"A": "Projeto de lei complementar.", "B": "Projeto de decreto legislativo.", "C": "Projeto de lei enviado pelo Poder Judiciário.", "D": "Projeto de resolução.", "E": "Moção de aplauso."}'::jsonb,'C',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',30,'Processo Legislativo',null,'José, servidor público da Assembleia Legislativa do Estado do Maranhão, teve a sua demissão, aplicada após processo administrativo disciplinar, invalidada por decisão judicial. Nesse caso, de acordo com o Estatuto dos Servidores Públicos Civis do Estado do Maranhão, é correto dizer que se aplicará a José o instituto jurídico de','{"A": "reversão.", "B": "reintegração.", "C": "readaptação.", "D": "recondução.", "E": "aproveitamento. Conhecimentos Específicos"}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',31,'Administração Geral',null,'Considere que determinada Secretaria do Estado X publicou edital de concurso público para a contratação de novos servidores públicos. No entanto, após mudança específica na legislação, aprovada pela Assembleia Legislativa, que reduziu drasticamente a demanda por funcionários, a Secretaria verificou que o prosseguimento do concurso, cujas provas ainda não tinham sido sequer aplicadas, se tornou desnecessário. Nesse caso, é correto afirmar que a Secretaria','{"A": "pode revogar o edital, em conformidade com o princípio da autotutela.", "B": "deve manter o concurso, visto que o princípio da sindicabilidade impede que ele seja cancelado.", "C": "pode anular o concurso, visto que o princípio da conveniência foi violado.", "D": "deve modificar os dispositivos conflitantes do edital, conforme prescreve o princípio da indisponibilidade do interesse privado.", "E": "pode convalidar o concurso, constituindo exceção ao princípio da intranscendência subjetiva das ações."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',32,'Administração Geral',null,'Devido a sua importância para a Administração Pública, alguns princípios foram expressamente previstos na Constituição Federal de 1988. Acerca dos princípios expressos para a Administração Pública, analise as assertivas a seguir. I. O princípio da legalidade permite que a Administração Pública pratique apenas atos que não sejam vedados, taxativamente, por lei em sentido formal. II. O princípio da eficiência preceitua que as atribuições dos agentes públicos sejam realizadas com presteza e rendimento profissional. III. O princípio da moralidade impede que um agente público nomeie seu cônjuge para cargo comissionado no órgão em que trabalha. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "I e II, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',33,'Administração Geral',null,'A divisão dos serviços e das competências da Administração Pública nas Secretarias da Cultura, da Comunicação Social, da Fazenda, entre outras, como ocorre no Governo do Maranhão, é chamada de','{"A": "descentralização por outorga.", "B": "concessão geográfica.", "C": "permissão unilateral.", "D": "delegação por colaboração.", "E": "desconcentração administrativa."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',34,'Administração Geral',null,'Assinale a opção que apresenta o tipo de estrutura organizacional que, embora ofereça riscos de conflito em função da dupla subordinação, busca aproveitar as principais vantagens das estruturas funcional e divisional.','{"A": "Estrutura Territorial.", "B": "Estrutura Linear.", "C": "Estrutura Simples.", "D": "Estrutura Matricial.", "E": "Estrutura Mecanicista."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',35,'Administração Geral',null,'Com relação à Administração Pública e suas divisões doutrinárias, assinale a opção que apresenta um exemplo de Administração Indireta no Estado do Maranhão.','{"A": "Polícia Civil do Maranhão (PC-MA).", "B": "Universidade Estadual do Maranhão (UEMA).", "C": "Assembleia Legislativa do Maranhão (ALEMA).", "D": "Corpo de Bombeiros Militar do Maranhão (CBM-MA).", "E": "Procuradoria-Geral do Estado do Maranhão (PGE-MA)."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',36,'Administração Geral',null,'A Autarquia representa um serviço autônomo, criado por lei, com o intuito de executar atividades típicas da Administração Pública. Esse tipo de entidade, que goza de uma série de prerrogativas, possui grande importância na configuração do Estado Brasileiro, estando presente tanto em nível federal quanto estadual e municipal. Uma característica elementar das Autarquias reside no fato de que elas','{"A": "não se submetem ao controle hierárquico dos órgãos ministeriais.", "B": "são regidas predominantemente por regras de direito privado.", "C": "constituem entidades despersonalizadas juridicamente.", "D": "adquirem atribuições em decorrência do processo de publicização do setor público não-estatal.", "E": "não necessitam realizar concursos públicos para a contratação de pessoal."}'::jsonb,'A',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',37,'Administração Geral',null,'As opções a seguir apresentam princípios do conceito de empreendedorismo governamental, desenvolvido na obra “Reinventando o Governo”, à exceção de uma. Assinale-a.','{"A": "Governo competitivo.", "B": "Governo orientado por missões.", "C": "Governo preventivo.", "D": "Governo orientado para o mercado.", "E": "Governo centralizado."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',38,'Administração Geral',null,'O conjunto de ideias sobre modelos de administração pública que traz à luz o conceito de paradigma do cliente, no qual os cidadãos devem ter suas necessidades satisfeitas pelos serviços ofertados pela Administração Pública é conhecido como','{"A": "nova gestão pública.", "B": "patrimonialismo de desempenho.", "C": "absolutismo.", "D": "parlamentarismo.", "E": "corporativismo."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',39,'Administração Geral',null,'Considere que uma fábrica de pregos e parafusos, localizada na cidade de Imperatriz (MA), utilize o seguinte processo na produção: após a fabricação das peças, elas são examinadas individualmente e, caso sejam identificadas não-conformidades, a peça é descartada. Esse processo de qualidade utilizado pela fábrica se baseia em métodos da era','{"A": "da garantia de qualidade.", "B": "do controle de qualidade.", "C": "da inspeção de qualidade.", "D": "da gestão de qualidade total.", "E": "do monitoramento estatístico da qualidade."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',40,'Administração Geral',null,'William E. Deming, uma das principais referências no campo da qualidade, ficou conhecido por sua experiência bem-sucedida no Japão pós-guerra, revolucionando a indústria desse país. Com base nessa experiência, Deming elaborou alguns princípios, conhecidos como “14 pontos de Deming”, que deveriam ser usados como diretrizes para a implementação de qualidade, tendo, como orientação','{"A": "o aumento da independência entre os departamentos.", "B": "a priorização dos negócios com base no preço.", "C": "a eliminação de slogans para a força de trabalho.", "D": "o fortalecimento do medo de erros e falhas.", "E": "a ênfase nos lucros extraordinários de curto prazo."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',41,'Administração Geral',null,'Em uma situação hipotética, o Governador do Estado Y, buscando embasamento para a elaboração de novas políticas públicas, solicitou a seus assessores que realizassem um estudo sobre a possível relação entre a melhoria da educação e a redução da violência no estado. Acerca do proposto pelo Governador, assinale a opção que apresenta uma ferramenta de qualidade adequada para esse estudo.','{"A": "Matriz GUT.", "B": "Diagrama de dispersão.", "C": "Folha de verificação.", "D": "5S.", "E": "6 Sigma."}'::jsonb,'B',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',42,'Administração Geral',null,'A gestão por resultados começou a ser implementada no Brasil após o Plano Diretor de Reforma do Aparelho do Estado (PDRAE), instituído no ano de 1995, em um momento de intensos debates acerca da reformulação do papel do Estado no contexto de globalização. Diante do exposto, acerca da gestão por resultados, é correto afirmar que','{"A": "retoma modelos participativos utilizados no modelo weberiano, como conselhos de políticas públicas e audiências públicas.", "B": "baseia-se na intensificação dos mecanismos de controle, fortalecendo regras autorreferentes.", "C": "exige a previsibilidade de funcionamento, reduzindo a autonomia dos gestores públicos.", "D": "delineia os objetivos com maior precisão, otimizando o exercício da accountability.", "E": "estimula a criação de símbolos de autoridade, encorajando o respeito hierárquico ao superior."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',43,'Administração Geral',null,'Os dados, obtidos pelo administrador, decorrentes da classificação dos materiais permitem que se dê atenção prioritária a determinados materiais da organização. Nesse sentido, destaca-se a importância do sistema de classificação utilizado, que, segundo a literatura, deve ter atributos como','{"A": "a praticidade, abordando um vasto número de características dos materiais para evitar duplicidades.", "B": "a flexibilidade, permitindo interfaces entre os diversos tipos de classificação e proporcionando uma visão global do material.", "C": "a abrangência, exigindo julgamentos simples e diretos do classificador, sem o emprego de conceitos abstratos.", "D": "a oportunidade, garantindo que as classificações permitam a distinção dos itens mesmo com análises intempestivas.", "E": "a materialidade, preceituando o uso de informações de fontes confiáveis, para possibilitar o consenso entre diferentes examinadores."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',44,'Direito Administrativo',null,'Em 2021 foi aprovada a Nova Lei de Licitações e Contratos (Lei nº 14.133/2021) para disciplinar, entre outras questões, as compras realizadas pela Administração Pública. Acerca dessa Nova Lei de Licitações e Contratos, é correto afirmar que','{"A": "é aplicável a toda a Administração Pública, sem exceções.", "B": "revogou imediatamente a Lei nº 8.666/1993, responsável por reger as compras públicas até então.", "C": "excluiu a possibilidade de pregão como modalidade de compra.", "D": "permite a continuidade do uso da Lei nº 8.666/1993 nos contratos em vigor celebrados sob a égide da antiga Lei de Licitações.", "E": "pode ser utilizada em combinação com os dispositivos da Lei nº 8.666/1993, possibilitando maior celeridade."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',45,'Administração Geral',null,'A curva ABC é um método amplamente utilizado na gestão de materiais, tendo, como um de seus resultados a identificação','{"A": "dos itens de estoque da categoria A, que representam os itens mais importantes para a organização.", "B": "dos itens de estoque de categoria B, que podem ser usados como substitutos, em caso de falta de itens necessários.", "C": "dos itens de estoque da categoria C, que possuem máxima criticidade operacional.", "D": "de itens de estoque da categoria A, que representam os materiais de menor valor.", "E": "de itens de estoque da categoria B, que fazem parte dos imobilizados pertencentes à organização."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',46,'Administração Geral',null,'Em uma empresa pública responsável por realizar a administração portuária, o estoque de determinada peça de manutenção é consumido na razão de 1.000 unidades por mês, sendo o seu tempo de reposição de 2 meses. Considerando que o estoque mínimo exigido para essa peça equivale a 1 mês de consumo, o ponto do pedido (ressuprimento) será de','{"A": "nenhuma unidade.", "B": "1000 unidades.", "C": "2000 unidades.", "D": "3000 unidades.", "E": "4000 unidades."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',47,'Administração Geral',null,'Com relação às possíveis estratégias de compra utilizadas por uma organização, analise as assertivas a seguir. I. A verticalização tem, como desvantagem, custos estruturais significativos. II. Enquanto a descentralização se sobressai em mercados de baixa previsibilidade, a centralização permite que a organização tenha ganhos de escala. III. A independência em relação ao mercado, de forma geral, é um dos diferenciais da horizontalização, característica que permite maior grau de customização produtiva. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "I e II, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',48,'Administração Geral',null,'Em função dos novos contextos da sociedade, a gestão de materiais tem se adaptado e buscado novas soluções para fazer frente aos problemas considerados mais urgentes a serem enfrentados. Nesse sentido,','{"A": "a paletização, embora gere atrasos por ineficiente aproveitamento do espaço, previne as perdas e desperdícios por mau acondicionamento.", "B": "o Kanban permite a eliminação da necessidade de estoques, por meio do emprego do sistema de produção empurrada.", "C": "a metodologia ágil redesenha radicalmente os processos, priorizando conceitos de acessibilidade, minimizando o uso de sistemas de informação.", "D": "o Supply Chain Management reduz a necessidade de mão-de- obra, aproveitando-se de sistemas de parceria e terceirização, reduzindo os custos sociais.", "E": "a logística reversa possibilita coletar ou recuperar os resíduos do produto após seu consumo, reforçando o desenvolvimento sustentável."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',49,'Administração Geral',null,'Uma empresa maranhense de turbinas de geração eólica vendeu 100 turbinas em 2021 e 130 em 2022. Caso ela utilize a projeção como modelo de previsão de demanda de materiais, deve esperar vender, em 2023,','{"A": "100 turbinas.", "B": "115 turbinas.", "C": "130 turbinas.", "D": "160 turbinas.", "E": "169 turbinas."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',50,'Administração Geral',null,'No caso de uma empresa operar em um mercado consumidor de alta sazonalidade, a exemplo do mercado de chocolates, que atinge picos de venda em datas festivas, é adequado o uso do estoque','{"A": "em trânsito.", "B": "de antecipação.", "C": "de desacoplamento.", "D": "ponderado.", "E": "por just-in-time."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',51,'Arquivologia',null,'O que determina a idade dos documentos (corrente, intermediária e permanente) é','{"A": "o valor legal.", "B": "o valor probatório.", "C": "a frequência de uso.", "D": "a existência de código de classificação.", "E": "a existência de instrumento de pesquisa."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',52,'Arquivologia',null,'Uma atividade que deve ser realizada no Arquivo Corrente é','{"A": "o arranjo.", "B": "a avaliação.", "C": "a descrição.", "D": "a elaboração de instrumentos de pesquisa.", "E": "a ordenação dos documentos em fundos."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',53,'Arquivologia',null,'O objetivo do protocolo é','{"A": "analisar o perfil dos usuários do arquivo.", "B": "avaliar e selecionar os documentos.", "C": "reduzir a massa documental ao essencial.", "D": "determinar o valor dos documentos.", "E": "controlar os documentos que tramitam no órgão."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',54,'Arquivologia',null,'A eliminação mecânica de todas as sujidades que se encontram nos documentos e nos agentes considerados agressores, tais como os clipes e grampos, oxidados ou não, os elementos utilizados como marcadores de folhas, as poeiras e demais elementos artificiais à estrutura física do documento, é denominada','{"A": "alisamento.", "B": "desinfestação.", "C": "fumigação.", "D": "higienização.", "E": "restauração."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',55,'Arquivologia',null,'São exemplos de métodos de arquivamento por assunto:','{"A": "duplex, decimal e enciclopédico.", "B": "alfabético, geográfico e numérico simples.", "C": "numérico cronológico, decimal e unitermo.", "D": "dígito-terminal, duplex e unitermo.", "E": "geográfico, dicionário e decimal."}'::jsonb,'A',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',56,'Redação Oficial',null,'Na correspondência oficial, é muito comum a presença de pronomes de tratamento em forma abreviada. Assinale a forma de abreviação corretamente indicada.','{"A": "Vossa Excelência: V. Excia.", "B": "Vossas Excelências: VV. Excias.", "C": "Vossa Santidade: V. Se.", "D": "Vossas Majestades: VV. MM.", "E": "Vossa Alteza: V. Alt."}'::jsonb,'X',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',57,'Redação Oficial',null,'Em relação aos pronomes de tratamento, assinale a construção inadequada.','{"A": "Sua Excelência deseja fazer agora o discurso?", "B": "Sua Excelência, Senhor Ministro, está passando bem?", "C": "Vossa Excelência deseja rever o projeto?", "D": "Vossas Excelências, Srs. Ministros, querem declarar algo?", "E": "Vossa Majestade quer subscrever o manifesto?"}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',58,'Redação Oficial',null,'O emprego correto dos sinais de pontuação é uma necessidade da escritura oficial. Assinale a frase que mostra pontuação adequada.','{"A": "Uma pequena obra da qual ninguém poderá dizer sem injustiça que não tem pé nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé.", "B": "Uma pequena obra da qual ninguém poderá dizer, sem injustiça, que não tem pé nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé.", "C": "Uma pequena obra da qual ninguém poderá dizer, sem injustiça, que não tem pé, nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé.", "D": "Uma pequena obra da qual ninguém poderá dizer, sem injustiça, que não tem pé nem cabeça: nela ao contrário tudo é, ao mesmo tempo, cabeça e pé.", "E": "Uma pequena obra da qual ninguém poderá dizer sem injustiça, que não tem pé nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',59,'Redação Oficial',null,'A Redação Oficial é, obrigatoriamente, impessoal e objetiva. Assinale a frase que segue esses parâmetros.','{"A": "A Constituição foi construída de modo apressado e, por isso, necessita de tantas interferências.", "B": "Maravilhosa essa ideia de arquivarmos toda a correspondência na forma digital.", "C": "Acredito que será altamente benéfica a viagem do Presidente ao Oriente.", "D": "Sem dúvida, a inflação brasileira sofrerá forte queda no segundo semestre.", "E": "A comitiva presidencial chegará amanhã, às 7h, ao aeroporto de Brasília."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',60,'Redação Oficial',null,'“Apurado, com impressionante agilidade e precisão, naquela tarde de 2009, o resultado da consulta à população acreana, verificou- se que a esmagadora e ampla maioria da população daquele distante estado manifestou-se pela efusiva e indubitável rejeição da alteração realizada pela Lei nº 11.662/2008. Não satisfeita, inconformada e indignada, com a nova hora legal vinculada ao terceiro fuso, a maioria da população do Acre demonstrou que a ela seria melhor regressar ao quarto fuso, estando cinco horas a menos que em Greenwich”. O período acima foi incluído no Manual de Redação da Presidência da República como exemplo de um problema redacional que deve ser evitado, que é','{"A": "a não observância das regras da norma culta.", "B": "a inadequação no emprego de sinais gráficos.", "C": "a prolixidade, ou seja, o exagero desnecessário de palavras.", "D": "a seleção erudita, excessivamente culta, de vocábulos.", "E": "o desrespeito no emprego de letras maiúsculas."}'::jsonb,'C',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno')
insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',15,'Língua Portuguesa',null,'Observe a seguir o início de um texto. “’Há muita gente complicando a vida do prefeito, inclusive o próprio prefeito’, costuma dizer um vereador. Trata-se de uma revelação de caráter generalizado na Câmara.” A introdução desse texto deve ser identificada como:','{"A": "alusão histórica;", "B": "interrogação;", "C": "suspense;", "D": "convite;", "E": "citação. Tipo 1 – Branca – Página 5 Legislação Específica e Noções de Direito"}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',16,'Direito Administrativo',null,'Ana, estudiosa da Administração Pública indireta, questionou Pedro a respeito da compatibilidade dos conceitos de personalidade jurídica e órgão despersonalizado com o referencial de descentralização administrativa. Pedro respondeu, corretamente, que:','{"A": "entes personificados e órgãos despersonalizados serão integrados, ou não, ao referido referencial, conforme haja, ou não, determinação legal nesse sentido;", "B": "o mencionado referencial é incompatível com a concepção de personalidade jurídica, sendo esta última própria do ente federativo dotado de autonomia política;", "C": "apenas os entes personalizados, não os órgãos despersonalizados, ainda que tenham maior liberdade decisória, se ajustam ao mencionado referencial;", "D": "o mencionado referencial é indiferente à natureza das estruturas que venham a integrá-lo, sendo direcionado pelo atendimento a uma finalidade de interesse público e pela autonomia decisória;", "E": "o órgão despersonalizado somente passará a integrar o mencionado referencial caso sua criação tenha sido autorizada em lei."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',17,'Direito Administrativo',null,'O Estado Alfa editou a Lei Complementar nº XX, que restringiu determinado direito fundamental de maneira flagrantemente oposta aos balizamentos estabelecidos pela Constituição da República de 1988, o que levou o Supremo Tribunal Federal (STF) a declarar a sua inconstitucionalidade. Na medida em que normas semelhantes foram editadas por outros entes federativos, dando ensejo a uma série de demandas judiciais, o Supremo Tribunal Federal veio a editar a Súmula Vinculante nº YY. Apesar disso, o Estado Alfa editou a Lei Complementar nº ZZ, cópia fiel da Lei Complementar nº XX e que se mostrava totalmente incompatível com a Súmula Vinculante nº YY. À luz da sistemática constitucional, é correto afirmar que a declaração de inconstitucionalidade da Lei Complementar nº XX:','{"A": "embora produza efeitos erga omnes, não impedia o Estado Alfa de editar a Lei Complementar nº ZZ, de idêntico teor, mas a Súmula Vinculante o impedia, sendo cabível a reclamação endereçada ao STF por inobservância da última;", "B": "e a existência da Súmula Vinculante nº YY, por serem aplicáveis exclusivamente ao caso concreto, não obstavam a edição, pelo Estado Alfa, da Lei Complementar nº ZZ;", "C": "por produzir efeitos erga omnes, impedia que o Estado Alfa editasse a Lei Complementar nº ZZ, de idêntico teor, sendo cabível a reclamação endereçada ao STF;", "D": "e a existência da Súmula Vinculante nº YY, por não serem oponíveis ao Poder Legislativo, não obstavam a edição, pelo Estado Alfa, da Lei Complementar nº ZZ;", "E": "acarretou a supressão da competência legislativa do Estado Alfa na matéria, o que torna injurídica a edição da Lei Complementar nº ZZ."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',18,'Direito Administrativo',null,'João, servidor público federal, recebeu delegação, da autoridade máxima da pessoa jurídica de direito público a que estava vinculado, para a prática de determinados atos administrativos. Ao ser cientificado da delegação, buscou se inteirar a respeito da possibilidade de a mesma competência ser exercida pela autoridade delegante, bem como se o ato a ser praticado seria atribuído a ele ou a esta autoridade. Por fim, concluiu, corretamente, que, à luz da Lei nº 9.784/1999:','{"A": "durante a delegação, os atos praticados pelo delegado precisam ser chancelados pelo delegante, sendo sempre atribuída a autoria do ato a este último agente;", "B": "durante a delegação, haverá uma concorrência de competências entre a autoridade delegante e a autoridade delegada, sendo sempre atribuído ao delegante o ato que venha a ser praticado;", "C": "durante a delegação, haverá uma concorrência de competências entre a autoridade delegante e a autoridade delegada, sendo atribuído ao respectivo subscritor o ato que venha a ser praticado;", "D": "a autoridade delegante não poderá praticar nenhum ato afeto ao objeto da delegação, durante todo o período em que esta última perdurar, sendo considerados de sua autoria os atos praticados pelo delegado;", "E": "a autoridade delegante, em caráter excepcional e por motivos relevantes, devidamente justificados, poderá avocar, temporariamente, a competência delegada, mas serão atribuídos ao delegado os atos que este agente praticar."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',19,'Direito Administrativo',null,'O Tribunal de Contas do Estado Alfa rejeitou as contas apresentadas por João, servidor ocupante de cargo de provimento efetivo, em razão de sua atuação como ordenador de despesas no âmbito da autarquia estadual Beta. Irresignado com a decisão, interpôs recurso hierárquico direcionado à Assembleia Legislativa do Estado Alfa com o requerimento de reforma da decisão. À luz desse quadro, o sindicato dos servidores do Tribunal de Contas do Estado Alfa consultou o seu advogado a respeito da compatibilidade desse recurso com a Constituição da República de 1988, sendo-lhe respondido, corretamente, que o recurso é:','{"A": "cabível, em simetria com o modelo federal e independente de previsão em lei estadual específica, pois o Tribunal de Contas é órgão auxiliar do Poder Legislativo;", "B": "cabível, em simetria com o modelo federal, desde que o recurso esteja previsto na Constituição Estadual, pois o Tribunal de Contas é órgão auxiliar do Poder Legislativo;", "C": "cabível, em simetria com o modelo federal, desde que previsto na lei de organização do Tribunal de Contas, pois esta estrutura orgânica é órgão auxiliar do Poder Legislativo;", "D": "incabível, pois as decisões proferidas pelo Tribunal de Contas possuem caráter definitivo, não podendo ser revistas por nenhuma estrutura orgânica, incluindo os Poderes Legislativo e Judiciário;", "E": "incabível, pois a competência para julgar as contas dos ordenadores de despesas foi outorgada, pela ordem constitucional, ao Tribunal de Contas, não havendo previsão de recurso para o Poder Legislativo. Tipo 1 – Branca – Página 6"}'::jsonb,'E',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',20,'Direito Administrativo',null,'O secretário de Transportes do Estado Alfa solicitou que sua assessoria desenvolvesse estudos a respeito de determinado serviço público que se mostrava de vital importância para a coletividade. Ao formular a solicitação, o secretário frisou que almejava saber se era obrigatória a sua prestação diretamente pelo Estado. Em resposta, a assessoria respondeu, corretamente, que essa espécie de serviço:','{"A": "pode ser prestada diretamente pelo Estado ou, indiretamente, apenas em regime de concessão ou permissão, observados os requisitos estabelecidos pela ordem jurídica;", "B": "pode ser prestada diretamente pelo Estado ou, indiretamente, em regime de autorização, permissão ou concessão, sendo sempre antecedida de licitação;", "C": "em regimes de livre iniciativa, como o brasileiro, não precisaria ser prestada diretamente pelo Estado, podendo ser livremente explorada pelo setor privado;", "D": "em razão do princípio da prevalência do interesse público sobre o privado, somente pode ser explorada diretamente pelo Estado;", "E": "em razão da indisponibilidade dos interesses envolvidos, somente pode ser prestada pela Administração Pública direta ou indireta."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',21,'Direito Administrativo',null,'Em razão de apuração sumária realizada no âmbito do Município Alfa, constatou-se que a sociedade empresária Beta fraudou a realização de determinado ato do procedimento licitatório público no qual se saíra vencedora, o que se enquadraria como ato lesivo à Administração Pública tipificado na Lei nº 12.846/2013. Instada a apresentar esclarecimentos, a sociedade empresária Beta manifestou o seu interesse em celebrar acordo de leniência. À luz da narrativa apresentada, é correto afirmar que o acordo de leniência alvitrado:','{"A": "não pode ser celebrado, já que incompatível com condutas dolosas praticadas em detrimento do processo licitatório;", "B": "pode ser celebrado, caso preenchidos os demais requisitos exigidos, e só disciplinará a forma de ressarcimento do dano, devendo ser homologado em juízo para produzir efeitos;", "C": "pode ser celebrado, caso preenchidos os demais requisitos exigidos, e afastará a incidência de todas as sanções cominadas, não carecendo de homologação judicial;", "D": "pode ser celebrado, caso preenchidos os demais requisitos exigidos, e afastará a incidência de algumas sanções, nos planos administrativo e judicial, não carecendo de homologação judicial;", "E": "somente pode ser celebrado pelo Ministério Público, não pelo Município, devendo ser preenchidos os requisitos previstos, além de ser exigida a homologação judicial caso afaste alguma sanção."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',22,'Direito Administrativo',null,'A fundação de direito privado Beta pretendia solicitar ao órgão competente do Estado Alfa a sua qualificação como organização social, mas tinha dúvidas em relação aos requisitos a serem preenchidos e às consequências dessa qualificação. Ao consultar o seu advogado, foi corretamente informado a Beta que:','{"A": "não é possível a obtenção da qualificação almejada, que somente pode ser deferida para as associações;", "B": "a qualificação está condicionada à participação, no Conselho de Administração, entre outros membros, de representantes do poder público;", "C": "a qualificação está condicionada à distribuição de lucros, aos membros do Conselho Curador, na proporção máxima de 5% do proveito patrimonial obtido;", "D": "a qualificação independe de qualquer ato formal, bastando que Beta seja estruturada da forma prevista em lei, o que lhe permitirá celebrar contratos de gestão;", "E": "a qualificação é obtida a partir da celebração de contrato de gestão, ocasião em que Beta assumirá o compromisso de praticar os atos ajustados com o poder público."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',23,'Direito Administrativo',null,'Maria, servidora pública, ocupante de cargo de provimento efetivo no Estado do Tocantins, foi acusada da prática de infração disciplinar que teve efetiva lesividade ao erário, mas não tinha lesividade para o serviço. Ao ser cientificada da instauração do processo disciplinar, consultou o seu advogado a respeito da possibilidade de, à luz dos balizamentos legais, ser celebrado termo de compromisso de ajuste de conduta. Foi corretamente respondido a Maria que o referido termo:','{"A": "é incompatível com as características da infração disciplinar imputada a Maria;", "B": "somente poderia ter sido celebrado em momento anterior à instauração do processo disciplinar;", "C": "pode ser celebrado a qualquer tempo, desde que Maria efetue o pagamento da multa punitiva prevista em lei;", "D": "é incompatível com o processo administrativo disciplinar, em razão da indisponibilidade da pretensão punitiva;", "E": "pode ser celebrado a qualquer tempo, desde que Maria, previamente, promova o ressarcimento do dano ao erário. Tipo 1 – Branca – Página 7"}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',24,'Direito Administrativo',null,'A deputada federal Sônia, ao perceber sérios desequilíbrios na concorrência em determinado setor econômico, solicitou que sua assessoria analisasse a compatibilidade, com a ordem constitucional, de uma proposição legislativa que estabelecesse critérios especiais de tributação, aplicáveis em todos os níveis federativos, com o objetivo de contornar esse quadro, prevenindo tais desequilíbrios. A assessoria respondeu, corretamente, que tal proposição é:','{"A": "incompatível com a ordem constitucional, pois o mercado deve regular a si próprio, não sendo admitida a intervenção estatal;", "B": "incompatível com a ordem constitucional, pois, apesar de ser possível o uso da tributação para fins extrafiscais, isto não pode afetar a livre iniciativa;", "C": "compatível com a ordem constitucional, desde que resguardada a competência de cada ente federativo para, mediante lei ordinária, buscar igual objetivo;", "D": "compatível com a ordem constitucional, desde que veiculada em lei complementar, o que não afasta a competência da União para, por lei ordinária, buscar igual objetivo;", "E": "incompatível com a ordem constitucional, pois normas editadas pela União, por força do pacto federativo, não podem afetar a competência tributária dos demais entes."}'::jsonb,'D',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',25,'Direito Administrativo',null,'O órgão competente do Estado Beta recebeu notícia, embasada em fartos elementos probatórios, indicando que João, servidor público ocupante de cargo de provimento efetivo, praticara atos de tortura, no exercício da função, em detrimento de diversas crianças alcançadas por sua atuação funcional. De acordo com o noticiante, tais condutas configuravam atos de improbidade administrativa tipificados na Lei nº 8.429/1992, devendo ser adotadas as providências cabíveis nessa seara, sem prejuízo da responsabilização administrativa e criminal de João. Instada a se manifestar, a assessoria jurídica observou, corretamente, que João:','{"A": "não pode ser responsabilizado por ato de improbidade administrativa, já que sua conduta não se enquadra na tipologia da Lei nº 8.429/1992;", "B": "somente pode ser responsabilizado por ato de improbidade administrativa tipificado na Lei nº 8.429/1992 caso seja previamente condenado na instância penal;", "C": "somente pode ser alcançado por uma instância de responsabilização, o que decorre do princípio que veda a responsabilização em duplicidade pelo mesmo fato;", "D": "somente pode ser responsabilizado por ato de improbidade administrativa tipificado na Lei nº 8.429/1992 caso o regime jurídico dos servidores tenha previsto a aplicação dessa lei;", "E": "pode ser responsabilizado por ato de improbidade administrativa tipificado na Lei nº 8.429/1992, já que sua conduta afrontou os princípios regentes da atividade estatal. Controle Externo"}'::jsonb,'A',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',27,'Direito Administrativo',null,'O Tribunal de Contas do Estado Beta recebeu, para análise, as contas de governo do prefeito do Município Alfa. Considerando os balizamentos estabelecidos pela Constituição da República de 1988, a referida análise deve:','{"A": "realizar amplo juízo valorativo a respeito das contas, podendo aplicar multa e imputar os débitos que sejam identificados, sem prejuízo do julgamento político a cargo da Câmara Municipal de Alfa, que só rejeitará o parecer por maioria qualificada;", "B": "se restringir à emissão de parecer prévio, que só deixará de prevalecer por maioria qualificada de votos da Câmara Municipal de Alfa, sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo;", "C": "se restringir à emissão de parecer prévio, que só deixará de prevalecer por maioria qualificada de votos da Câmara Municipal de Alfa, não sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo;", "D": "julgar as contas, realizando amplo juízo valorativo a respeito das informações apresentadas, sendo que a sua decisão somente deixará de prevalecer pelo voto de dois terços dos membros da Câmara Municipal de Alfa;", "E": "se restringir à emissão de parecer prévio, que só deixará de prevalecer pela unanimidade dos votos da Câmara Municipal de Alfa, sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo. Tipo 1 – Branca – Página 8"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',28,'Direito Administrativo',null,'João, servidor público ocupante de cargo de provimento efetivo, que atuara como ordenador de despesas no Município Alfa, foi condenado em processo administrativo, no âmbito do Tribunal de Contas do Estado do Tocantins, pela prática de infração considerada grave. Nesse caso, João:','{"A": "somente pode ser condenado à sanção de multa, além de ter a obrigação de ressarcir os danos que tenha causado ao erário;", "B": "deve ser sempre condenado à sanção de multa, além de ser considerado em débito, se for o caso, ficando ainda inabilitado, nos termos da lei, para o exercício de cargo em comissão ou função de confiança;", "C": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inabilitado, por decisão tomada por maioria absoluta, nos termos da lei, para exercer cargo em comissão ou função de confiança;", "D": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inelegível, por decisão tomada por maioria absoluta, nos termos da lei, para exercer cargo eletivo estadual;", "E": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inelegível, por decisão tomada por maioria de dois terços, nos termos da lei, para exercer qualquer cargo eletivo."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',31,'Contabilidade Geral',null,'Quando da existência de inflação severa na economia, a premissa contábil básica ameaçada e que tem sua utilidade reduzida é a da:','{"A": "competência;", "B": "periodicidade;", "C": "continuidade;", "D": "entidade econômica;", "E": "unidade monetária."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',32,'Contabilidade Geral',null,'Durante o ano de 2022, uma empresa se envolveu em uma disputa tributária com o governo. Os advogados da empresa indicaram que era provável uma perda nessa disputa e que a empresa teria que pagar um valor entre R$ 800.000 e R$ 1.400.000 (nesse intervalo, nenhum valor é uma estimativa melhor que a outra). Após a emissão das demonstrações financeiras de 2022, o caso foi resolvido com o governo por R$ 1.200.000. Nesse caso, em 31 de dezembro de 2022, o contador da empresa deveria ter:','{"A": "reconhecido uma provisão de R$ 800.000;", "B": "reconhecido uma provisão de R$ 1.100.000;", "C": "reconhecido uma provisão de R$ 1.200.000;", "D": "reconhecido uma provisão de R$ 1.400.000;", "E": "divulgado em nota explicativa um valor de R$ 1.200.000 devido à baixa probabilidade. Tipo 1 – Branca – Página 9"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',33,'Contabilidade Geral',null,'Um ativo imobilizado adquirido em 1º de janeiro de 2019, com vida útil estimada em dez anos e valor residual igual a zero, é depreciado pelo método linear e, até o final de 2020, nenhuma perda por impairment nem benfeitorias foram realizadas. O valor contábil líquido do ativo após o teste de impairment em 31 de dezembro de 2020 era de R$ 385.000. Assim, a perda por impairment foi de R$ 15.000. Em 31 de dezembro de 2021, com base na melhoria das condições do mercado, o ativo foi reavaliado. Nesse caso, a empresa reverteu o valor máximo da perda por impairment permitida na demonstração do resultado de 2021 de:','{"A": "R$ 1.875;", "B": "R$ 13.125;", "C": "R$ 15.000;", "D": "R$ 336.875;", "E": "R$ 385.000."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',34,'Contabilidade Geral',null,'As ações em tesouraria adquiridas no mercado pela própria empresa devem ser divulgadas como um(a):','{"A": "conta redutora do patrimônio;", "B": "direito no ativo circulante;", "C": "investimento no ativo não circulante;", "D": "conta no passivo circulante;", "E": "conta no passivo não circulante."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',35,'Contabilidade Geral',null,'Informações sobre o fluxo de caixa de uma entidade são úteis para proporcionar aos usuários das demonstrações contábeis uma base para avaliar a capacidade de a entidade gerar caixa e equivalentes de caixa, bem como suas necessidades de utilização desses fluxos de caixa. A entidade pode escolher o método direto ou indireto para apresentar os fluxos de caixa das atividades operacionais. É correto afirmar que o método:','{"A": "direto é construído a partir do lucro líquido e apresenta as receitas e as despesas divulgadas na demonstração do resultado;", "B": "direto apresenta as principais classes de recebimentos brutos, pagamentos brutos e, caso a empresa escolha esse método, a conciliação entre o lucro líquido e o fluxo de caixa líquido das atividades operacionais deve ser fornecida;", "C": "indireto requer que os fluxos de caixa das atividades operacionais incluam os pagamentos de caixa para aquisição de ativo imobilizado, intangível e outros ativos de longo prazo;", "D": "indireto apresenta as principais classes de recebimentos brutos, pagamentos brutos, variações ocorridas no período nos estoques e nas contas operacionais a receber e a pagar;", "E": "indireto requer que os fluxos de caixa das atividades operacionais incluam as mudanças no percentual de participação em uma controlada e que não resultem na perda do controle."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',36,'Contabilidade Geral',null,'Uma empresa alugou uma propriedade na qual o petróleo foi descoberto. Poços nessa propriedade produziram 18 mil barris de petróleo durante o ano e foram vendidos a um preço médio de venda de R$ 65 por barril. Os recursos petrolíferos totais dessa propriedade são estimados em 250 mil barris. O arrendamento previa um pagamento total de R$ 600.000 ao arrendador (proprietário), antes que a perfuração pudesse ser iniciada, e um aluguel anual de R$ 31.500, mais um prêmio de 5% do preço de venda de cada barril de petróleo retirado que deve ser pago anualmente ao arrendador. Além disso, a empresa (arrendatária) deve limpar todos os resíduos e detritos da perfuração e arcar com esses custos quando os poços forem abandonados. O valor justo estimado a valor presente, no momento da locação, dessa limpeza e recondicionamento é de R$ 30.000. Assim, o custo por barril foi de:','{"A": "R$ 2,40;", "B": "R$ 3,25;", "C": "R$ 4,27;", "D": "R$ 7,40;", "E": "R$ 7,52."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',37,'Contabilidade Geral',null,'A empresa Z adquiriu uma participação de 14,7% na empresa X. Com a transação, a empresa Z terá direito de indicar dois membros para o conselho de administração da empresa X e, também, dará à compradora a preferência na distribuição dos produtos da empresa investida. Nessa operação, a empresa Z aplicará o método de:','{"A": "valor justo;", "B": "custo;", "C": "equivalência patrimonial;", "D": "custo corrente;", "E": "marcação a mercado."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',38,'Contabilidade Geral',null,'Uma empresa decidiu alugar um edifício que possui numa área nobre de uma cidade. Também espera que o edifício se valorize ao longo do tempo. Nesse caso, após o reconhecimento do edifício como propriedade para investimento, a empresa pode escolher como sua política contábil o método do:','{"A": "valor justo, e os futuros ganhos de valorização do edifício, se ocorrerem, deverão ser contabilizados no resultado do período em que ocorrerem;", "B": "custo, e os futuros ganhos de valorização do edifício, se ocorrerem, deverão ser contabilizados em outros resultados abrangentes no patrimônio líquido;", "C": "valor justo, e há que se reconhecer, periodicamente, a sua depreciação com base nas regras contábeis aplicáveis ao ativo imobilizado;", "D": "valor justo, e os futuros ganhos de valorização do edifício, se ocorrerem, deverão ser contabilizados em outros resultados abrangentes no patrimônio líquido;", "E": "custo, e os futuros ganhos de valorização do edifício, se ocorrerem, deverão ser contabilizados no resultado do período em que ocorrerem. Tipo 1 – Branca – Página 10"}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',39,'Contabilidade Geral',null,'Uma empresa celebrou um contrato com um cliente para construir um armazém por R$ 950.000 em 31 de março de 2022 com um bônus de desempenho de R$ 50.000 se a construção for concluída até 31 de julho de 2022. O bônus é reduzido em R$ 10.000 a cada semana que a conclusão estiver atrasada. A empresa incluiu esse bônus de conclusão em seu contrato e, com base numa estimativa apropriada, definiu os seguintes resultados: 65% de conclusão do contrato até 31 de julho de 2022; 25% de conclusão do contrato até 7 de agosto de 2022; 5% de conclusão do contrato até 14 de agosto de 2022; e 5% de conclusão do contrato até 21 de agosto de 2022. Assim, o valor da contraprestação fixa mais a variável é de:','{"A": "R$ 652.500;", "B": "R$ 685.000;", "C": "R$ 950.000;", "D": "R$ 995.000;", "E": "R$ 1.000.000."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',40,'Contabilidade Geral',null,'O CPC 06 (R2) objetiva garantir que arrendatários e arrendadores forneçam informações relevantes, de modo que representem fielmente essas transações. Nesse contexto, conforme a norma:','{"A": "o arrendamento é classificado como arrendamento operacional se transferir substancialmente todos os riscos e benefícios inerentes à propriedade do ativo subjacente;", "B": "o fato de o arrendamento ser arrendamento financeiro ou arrendamento operacional depende da essência da transação, em vez da forma do contrato;", "C": "o arrendamento é classificado como arrendamento financeiro se não transferir substancialmente todos os riscos e benefícios inerentes à propriedade do ativo subjacente;", "D": "o arrendatário deve classificar cada um de seus arrendamentos como arrendamento operacional ou arrendamento financeiro;", "E": "no reconhecimento inicial, o arrendatário pode escolher mensurar o ativo de direito de uso ao custo ou ao valor justo."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',41,'Contabilidade Geral',null,'Uma empresa se dedica à fabricação de diversos produtos. Os dados a seguir referem-se às divisões em que as operações foram conduzidas para o exercício encerrado em 31 de dezembro de 2022. Divisões Receitas Lucros Ativos em 31/12/2022 A R$ 8.000.000 R$ 1.320.000 R$ 16.000.000 B R$ 6.400.000 R$ 1.120.000 R$ 14.000.000 C R$ 4.800.000 R$ 960.000 R$ 10.000.000 D R$ 2.400.000 R$ 440.000 R$ 5.200.000 E R$ 3.400.000 R$ 540.000 R$ 5.600.000 F R$ 1.200.000 R$ 180.000 R$ 2.400.000 Totais R$ 26.200.000 R$ 4.560.000 R$ 53.200.000 A partir das informações apresentadas, a empresa utilizará os parâmetros mínimos quantitativos para definir a quantidade de segmentos divulgáveis. Dessa forma, a empresa possui:','{"A": "dois segmentos divulgáveis;", "B": "três segmentos divulgáveis;", "C": "quatro segmentos divulgáveis;", "D": "cinco segmentos divulgáveis;", "E": "seis segmentos divulgáveis."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',42,'Contabilidade Geral',null,'Uma empresa apresentou o seguinte Balanço Patrimonial em 31 de dezembro de 20x2. Balanço Patrimonial (31 de dezembro de 20x2) ATIVO R$ PASSIVO R$ Circulante 713.000 Circulante 186.000 Disponível 20.000 Obrigações Sociais 51.000 Aplicações Financeiras 288.000 Fornecedores 41.000 Contas a Receber 145.000 Empréstimos 70.000 Estoques 260.000 Provisões 24.000 Não Circulante 33.884 Empréstimos 33.174 Não Circulante 120.841 Provisões 710 Ativo Realizável a Longo Prazo 2.916 Patrimônio Líquido 613.957 Investimentos 412 Capital Social 471.302 Imobilizado 87.071 Reservas de Capital 4.502 Intangível 30.442 Reservas de Lucros 138.153 Totais 835.390 Totais 835.390 A partir das informações apresentadas, a liquidez seca e a liquidez corrente são, respectivamente:','{"A": "0,11 e 3,85;", "B": "1,75 e 0,11;", "C": "2,44 e 3,83;", "D": "3,83 e 2,44;", "E": "3,83 e 4,40. Tipo 1 – Branca – Página 11"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',43,'Contabilidade Geral',null,'Por solicitação de um órgão de controle externo, uma entidade pública necessitou avaliar um conjunto de ativos com características comuns a valor corrente. Após a realização da avaliação e envio do relatório, o órgão de controle emitiu um comunicado de inconsistência e pediu retificação da avaliação. No relatório foi verificado um equívoco ao indicar que foi usado como critério de avaliação o:','{"A": "custo de reposição;", "B": "preço líquido de venda;", "C": "preço presumido;", "D": "valor de mercado;", "E": "valor em uso."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',44,'Contabilidade Pública',null,'Ao tratar da estrutura de apresentação das demonstrações contábeis das entidades públicas, o Manual de Contabilidade Aplicada ao Setor Público (MCASP) traz disposições para inclusão de informações comparativas. Ao elaborar as demonstrações contábeis de uma entidade, um analista contábil deve considerar que, em regra, a informação comparativa:','{"A": "deve ser divulgada em referência a pelo menos dois exercícios anteriores ao período corrente;", "B": "deve ser divulgada referente ao período anterior para todos os montantes apresentados do período corrente;", "C": "é aplicável somente na apresentação do balanço patrimonial, em decorrência da natureza das informações;", "D": "pode ser apresentada, alternativamente, como informação adicional em notas explicativas;", "E": "tem divulgação facultativa, mas é fortemente incentivada para dar maior transparência e facilitar o controle social."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',45,'Contabilidade Pública',null,'A estrutura de apresentação do balanço patrimonial em convergência com os padrões internacionais de contabilidade aplicada ao setor público apresentou algumas alterações, que estão consolidadas no MCASP. Nesse contexto, um item informacional que deve ter seu saldo apresentado no quadro principal do balanço patrimonial é:','{"A": "ativo financeiro;", "B": "demandas judiciais;", "C": "dívida consolidada líquida;", "D": "garantias concedidas;", "E": "investimentos."}'::jsonb,'E',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',46,'Contabilidade Pública',null,'A Demonstração das Variações Patrimoniais (DVP), conforme previsto na Lei nº 4.320/1964, evidenciará as alterações verificadas no patrimônio do ente ao longo do exercício financeiro. De acordo com o MCASP, tais alterações:','{"A": "devem considerar operações extraorçamentárias;", "B": "devem se circunscrever à execução orçamentária;", "C": "permitem avaliar o desempenho financeiro do ente;", "D": "possibilitam a apuração do resultado patrimonial do exercício;", "E": "são registradas nas contas das classes 1 e 2 do PCASP."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',47,'Contabilidade Pública',null,'O Balanço Orçamentário é um demonstrativo que traz informações sobre a execução de receitas e despesas ao longo do exercício financeiro. Ao analisar esse demonstrativo, a única informação relativa à receita que NÃO se encontra detalhada para fins de análise é o montante do(a):','{"A": "previsão atualizada da receita;", "B": "receita arrecadada;", "C": "receita inicialmente prevista;", "D": "receita lançada;", "E": "saldo a arrecadar."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',48,'Contabilidade Pública',null,'Ao implantar o Plano de Contas Aplicado ao Setor Público (PCASP), o gestor contábil de uma entidade pública tinha algumas dúvidas sobre eventuais mudanças no tratamento dos atos de gestão cujos efeitos possam produzir modificações no patrimônio da entidade. Como regra geral e no contexto da convergência às normas internacionais de contabilidade aplicada ao setor público, o PCASP dispõe que tais atos:','{"A": "devem ser evidenciados, quando relevantes, em notas explicativas;", "B": "devem ser registrados em contas de controles devedores e de controles credores;", "C": "por serem atos administrativos, não são objeto de registro contábil;", "D": "são mantidos nas contas de compensação, quando legalmente previstas;", "E": "são registrados em contas de natureza patrimonial, dado o potencial impacto no patrimônio."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',49,'Contabilidade Pública',null,'Uma entidade pública precisa fazer o registro contábil de uma despesa cujo fato gerador ocorreu antes do empenho. Sob a perspectiva da informação de natureza patrimonial, haverá um lançamento a débito em uma conta de variação patrimonial diminutiva e um lançamento a crédito em conta de:','{"A": "crédito a empenhar ou de fornecedores;", "B": "crédito a liquidar ou de disponibilidades;", "C": "crédito disponível ou de disponibilidades;", "D": "disponibilidades ou de fornecedores;", "E": "fornecedores ou de crédito em liquidação. Tipo 1 – Branca – Página 12"}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',50,'Contabilidade Pública',null,'Além de dispor sobre regras específicas relativas a metas fiscais e limites de gastos para promover uma gestão fiscal responsável, a Lei de Responsabilidade Fiscal (LRF) trata também da escrituração e da consolidação das contas públicas. À luz da LRF, para esses procedimentos, os responsáveis pela contabilidade das entidades públicas deverão considerar que:','{"A": "a despesa e a assunção de compromisso serão registradas segundo o regime de competência;", "B": "a disponibilidade de caixa observará o princípio da não vinculação de recursos;", "C": "as despesas previdenciárias devem ser apresentadas de forma conjunta e consolidada com as demais despesas da entidade;", "D": "as operações de crédito e as demais formas de financiamento deverão ser escrituradas em ordem crescente de exigibilidade;", "E": "os resultados dos fluxos financeiros de natureza previdenciária serão apurados pelo regime de caixa."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',51,'Contabilidade Pública',null,'Periodicamente os entes públicos precisam publicar relatórios para subsidiar o acompanhamento da execução orçamentária e da gestão fiscal. Além de serem instrumentos de transparência, constituem subsídios para o controle social. Se um agente da sociedade civil organizada desejar informações sobre o cumprimento das metas fiscais em um dado período, deverá consultar o anexo do Relatório Resumido da Execução Orçamentária (RREO) que versa sobre:','{"A": "alienação de ativos e aplicação dos recursos;", "B": "apuração da receita corrente líquida;", "C": "apuração dos resultados nominal e primário;", "D": "despesa com juros e refinanciamento da dívida;", "E": "restos a pagar e disponibilidade de caixa."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',52,'Contabilidade Pública',null,'Ao final do primeiro quadrimestre de um dado exercício, a Receita Corrente Líquida (RCL) de um ente estadual totalizou R$ 10 bilhões. O Relatório de Gestão Fiscal (RGF) do Poder Legislativo, incluindo o Tribunal de Contas, deve indicar, no anexo relativo à despesa com pessoal, que:','{"A": "naquele quadrimestre o limite máximo da despesa é de R$ 75 milhões;", "B": "nos últimos doze meses o limite máximo de referência equivale a R$ 300 milhões;", "C": "o limite de alerta equivale a R$ 225 milhões no referido período;", "D": "o limite prudencial será apurado somente no último quadrimestre do exercício;", "E": "tais gastos podem atingir até R$ 600 milhões sem comprometer os limites fiscais."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',53,'Contabilidade Pública',null,'No processo de adaptação aos padrões internacionais de contabilidade aplicada ao setor público foi necessário que as entidades adotassem uma lógica adicional além da ênfase no controle orçamentário, baseado na Lei nº 4.320/1964. Nesse contexto, na elaboração das suas demonstrações contábeis, as entidades públicas devem considerar que:','{"A": "as origens das alterações patrimoniais devem ser registradas conforme as etapas da receita e despesa;", "B": "o regime de caixa permanece integralmente aplicado no registro das receitas;", "C": "o regime de competência será adotado parcialmente no registro das despesas;", "D": "o regime patrimonial deve ser adotado facultativamente, mantendo as disposições legais;", "E": "todos os registros devem ser realizados pelo regime de competência."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',54,'Contabilidade Pública',null,'No início de um dado exercício financeiro, uma entidade pública desocupou um dos imóveis registrados no seu patrimônio que era usado em suas atividades administrativas. Após a desocupação, a gestão da entidade aprovou destinar a propriedade para auferir receitas de aluguel. Considerando as características do novo uso do imóvel, a entidade deve:','{"A": "adotar um dos modelos para mensuração de propriedade para investimento;", "B": "manter o imóvel como ativo imobilizado e revisar a sua vida útil;", "C": "realizar um teste de redução ao valor recuperável do imóvel pela transferência de uso;", "D": "reclassificar o imóvel como disponível para venda ou operação descontinuada;", "E": "tratar a transferência de uso do imóvel como uma transação sem contraprestação."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',55,'Contabilidade Pública',null,'Em grande parte das entidades públicas o maior volume de transações ocorre sem contraprestação. De acordo com as disposições do Manual de Contabilidade Aplicada ao Setor Público (MCASP), essas transações envolvem o recebimento de ativos ou serviços ou ainda a extinção de passivos e:','{"A": "não abrangem transações de natureza intergovernamental;", "B": "devem ser previstas no orçamento do ente no exercício da sua realização;", "C": "são controladas com o atributo F para fins de elaboração do balanço patrimonial;", "D": "são registradas em contas de controle, dada a sua natureza potencial;", "E": "sua contrapartida pode ser a entrega de um valor irrisório ou nenhum valor. Tipo 1 – Branca – Página 13"}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',56,'Contabilidade Pública',null,'Em 01/07/20x0, uma entidade pública contratou uma operação de crédito em um organismo internacional de financiamento, correspondente a 10 milhões de dólares. A transação está sujeita a uma taxa atrelada à variação da inflação do país, tem seis meses de carência e deverá ser quitada em cinco anos após esse período, com pagamentos semestrais. Para fins de apresentação das demonstrações contábeis do exercício encerrado em 31/12/20x0, o saldo em aberto dessa transação deverá:','{"A": "adotar o dólar como moeda de apresentação;", "B": "ser apresentado em moeda funcional pela taxa média de câmbio;", "C": "ser convertido pela taxa de fechamento;", "D": "ser convertido pela taxa real de câmbio da data da transação;", "E": "ser mensurado a valor justo em moeda funcional pela taxa de câmbio histórica."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',57,'Contabilidade Pública',null,'Um analista recém-empossado em uma entidade pública foi alocado para uma atividade que envolvia controle contábil de estoques, com apresentação periódica de relatórios para fins de acompanhamento dos custos pelo gestor da entidade. Nessa mesma época a entidade recebeu a título gratuito 1.000 caixas de um material usado em suas atividades operacionais, que foi destinado para o estoque. A entidade arcou apenas com o custo do transporte. Uma vez que a entidade adota as disposições e recomendações do Manual de Contabilidade Aplicada ao Setor Público (MCASP), no relatório periódico o analista deverá apresentar o registro do material pelo:','{"A": "valor recuperável;", "B": "valor realizável líquido;", "C": "valor justo na data da aquisição;", "D": "custo corrente de reposição;", "E": "custo médio ou valor líquido, dos dois, o menor."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',58,'Contabilidade Pública',null,'Nas operações de fusão, o Manual de Contabilidade Aplicada ao Setor Público (MCASP) detalha a aplicação do método modificado da união de participações. Uma das exigências desse método consiste em determinar a data da fusão, a qual pode ser aquela:','{"A": "definida nos termos da combinação, limitada a noventa dias após a assinatura;", "B": "em que a entidade resultante determina publicar suas primeiras demonstrações contábeis;", "C": "em que a entidade resultante entrega os ativos e assume os passivos das operações da combinação;", "D": "em que se comprova a difusão do controle das operações da combinação;", "E": "especificada no acordo para que a entidade obtenha o controle dos ativos e passivos das operações."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',59,'Contabilidade Pública',null,'Conforme disposições da Lei nº 4.320/1964, despesas que não cumpriram todos os estágios de execução da despesa orçamentária podem ser inscritas em restos a pagar. Os dispositivos legais que tratam desse mecanismo estabelecem que:','{"A": "a execução financeira dos restos a pagar deve ser priorizada no decreto de programação financeira;", "B": "a inscrição em restos a pagar é exigida para despesas abertas mediante créditos adicionais extraordinários;", "C": "é vedada a inscrição de despesas em restos a pagar no último ano de mandato;", "D": "informações sobre a execução dos restos a pagar devem ser apresentadas em relatórios fiscais quadrimestrais;", "E": "o limite de inscrição em restos a pagar está entre as exigências para a realização de transferência voluntária."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',60,'Contabilidade Pública',null,'Uma entidade que deseja gerar informações de custos para a sua gestão precisa adotar um sistema de acumulação que corresponde à forma como os custos são acumulados e apropriados aos bens e serviços e outros objetos de custos. No caso de a entidade precisar de um sistema que compreenda especificações predeterminadas do serviço demandado, deve adotar o sistema de custeio:','{"A": "baseado em atividade;", "B": "de acumulação contínua;", "C": "pleno ou variável;", "D": "por absorção ou direto;", "E": "por ordem de serviço ou produção."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',61,'Administração Financeira e Orçamentária',null,'O modelo orçamentário de referência para o planejamento das entidades públicas brasileiras é o orçamento-programa. A classificação programática da despesa está alinhada a esse modelo. Nesse contexto, um instrumento de programação que envolve um conjunto de operações que se realizam de modo contínuo e permanente e que contribuem para a manutenção da ação de governo, a exemplo de fiscalização e monitoramento da qualidade de combustíveis automotores, deve ser classificado como:','{"A": "aplicação direta;", "B": "atividade;", "C": "projeto;", "D": "operação especial;", "E": "encargo especial. Tipo 1 – Branca – Página 14"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',68,'Auditoria',null,'O objetivo do auditor é definir e executar procedimentos de auditoria que permitam a ele conseguir evidência de auditoria apropriada e suficiente que lhe possibilite obter conclusões razoáveis para fundamentar a sua opinião. Nesse sentido, a confiabilidade da evidência de auditoria é influenciada pela fonte, por sua natureza e é mais confiável quando obtida:','{"A": "de fontes independentes externas à entidade e confirmada em documento eletrônico ou em papel;", "B": "por meio da indagação a respeito da aplicação de controle, em vez da observação da aplicação de controle;", "C": "pela representação formal, pois fornece evidência de auditoria apropriada e suficiente;", "D": "pela cópia de um documento fiscal obtida por intermédio de fontes internas da empresa do que diretamente pelo auditor;", "E": "por meio da indagação a respeito da contagem de estoques, em vez da observação do auditor da contagem do estoque pelo pessoal da entidade. Tipo 1 – Branca – Página 15"}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Ciências Contábeis',2022,null,'Tipo 1',70,'Auditoria',null,'Existem diversos tipos de auditoria, contudo, uma delas possui características próprias que a distingue dos outros tipos. Dessa forma, a que apresenta uma variedade e complexidade de questões a serem tratadas, possui maior flexibilidade na escolha de temas, objetos de auditoria, métodos de trabalho e forma de comunicar suas conclusões é a auditoria:','{"A": "de conformidade;", "B": "financeira;", "C": "contábil;", "D": "operacional;", "E": "ambiental. DISCURSIVA 1 Após assumir o mandato para o qual foi eleito, o governador de um ente da Federação nomeou uma pessoa de sua confiança, mas não integrante do quadro de servidores, para a chefia da Divisão de Informações Fiscais da Secretaria Estadual de Fazenda. Uma das atribuições dessa divisão é preparar os relatórios fiscais do ente em atendimento às normas de elaboração e publicação. Como o novo chefe não conhecia todos os detalhes envolvidos, solicitou a um servidor experiente lotado na divisão que preparasse uma apresentação sobre o Relatório de Gestão Fiscal (RGF) com os seguintes tópicos: a) conteúdo dos anexos e periodicidade de divulgação do relatório; b) detalhamento dos limites fiscais aplicáveis ao ente que podem ser acompanhados pelo relatório; c) formas de divulgar e dar transparência ao conteúdo do RGF previstas na LRF. Elabore um texto com até 15 linhas com abordagem nos tópicos solicitados na apresentação que deve ser feita pelo servidor. Valor: 15 pontos Máximo de 15 linhas. Tipo 1 – Branca – Página 16 2 Por solicitação do governador e de outros secretários de áreas finalísticas, a Secretaria de Planejamento de um ente da Federação abriu uma série de créditos adicionais durante o último exercício financeiro, conforme detalhado a seguir. Crédito Data de abertura Finalidade Área funcional Valor da dotação Percentual empenhado I 02/05/2020 Prover recursos para uma despesa com dotação insuficiente Saúde R$ 43.000,00 100% II 04/10/2020 Prover recursos para uma despesa com dotação insuficiente Educação R$ 23.000,00 70% III 13/04/2020 Autorizar uma despesa não incluída originalmente no orçamento Segurança pública R$ 13.000,00 0% IV 20/09/2020 Autorizar uma despesa não incluída originalmente no orçamento Saneamento R$ 28.000,00 50% V 28/05/2020 Inserir no orçamento uma despesa urgente e imprevista, decorrente de calamidade pública Assistência social R$ 79.000,00 80% VI 03/11/2020 Inserir no orçamento uma despesa urgente e imprevista, decorrente de calamidade pública Ciência e tecnologia R$ 109.000,00 30% À luz das disposições legais sobre abertura e execução de créditos adicionais no orçamento anual, elabore um texto de até 15 linhas que explique os seguintes pontos: a) quais tipos de créditos adicionais se aplicam a cada uma das situações do quadro; b) quais recursos podem ser alocados para cobertura das novas despesas em cada caso; c) qual o tratamento previsto para esses créditos no encerramento do exercício financeiro; d) que demonstrativo contábil expressa diretamente o impacto da abertura desses créditos e de qual forma. Valor: 15 pontos Máximo de 15 linhas. Tipo 1 – Branca – Página 17 RASCUNHO - Prova Discursiva - Questão 1 1 5 10 15 RASCUNHO - Prova Discursiva - Questão 2 1 5 10 15"}'::jsonb,'D',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_ciencias_contabeisaudciecon_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','alternativa muito longa: pode conter texto de outra questão; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno')
insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',1,'Língua Portuguesa',null,'“A segurança pública, de forma conceitual, é uma atividade que deve ser prestada pelos órgãos estatais e pela comunidade como um todo que visa proteger a cidadania, de forma a prevenir e controlar atos de criminalidade.” Nesse primeiro período do texto, aparecem as seguintes informações sobre a segurança pública:','{"A": "o conceito de segurança pública e a história da sua criação.", "B": "as causas e as consequência da criação da segurança pública.", "C": "a definição do que seja a segurança pública e sua finalidade.", "D": "a razão da existência da segurança pública e sua história."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',2,'Língua Portuguesa',null,'“A segurança pública, de forma conceitual, é uma atividade que deve ser prestada pelos órgãos estatais e pela comunidade como um todo que visa proteger a cidadania, de forma a prevenir e controlar atos de criminalidade.” Também aprendemos, pela leitura desse segmento inicial do texto, que','{"A": "a única responsável pela segurança é a força policial.", "B": "a comunidade também deve participar da segurança.", "C": "o controle total de atos de criminalidade é impossível.", "D": "a prevenção trata das consequências dos atos criminosos."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',3,'Língua Portuguesa',null,'Segundo o texto, quando o serviço de segurança deixa de ser realizado de forma satisfatória','{"A": "torna-se necessária a mudança das regras de atuação.", "B": "a população passa a sofrer consequências graves.", "C": "a comunidade perde o direito à cidadania.", "D": "o povo perde a confiança no serviço de segurança."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',4,'Língua Portuguesa',null,'“Dada a importância constitucional desse serviço é que se conclui que o mesmo não pode ser executado de qualquer forma”. A maneira de reescrever esse segmento do texto que está adequada, mantendo-se as informações originais, é:','{"A": "A importância constitucional desse serviço conclui que o mesmo não pode ser executado de qualquer forma.", "B": "Conclui-se que o mesmo não pode ser executado de qualquer forma, dada a sua importância constitucional.", "C": "Não pode esse serviço ser executado de qualquer forma, pois esse serviço tem importância constitucional.", "D": "Dada a importância constitucional desse serviço, conclui-se que ele não pode ser executado de qualquer forma."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',5,'Língua Portuguesa',null,'“Dada a importância constitucional desse serviço é que se conclui que o mesmo não pode ser executado de qualquer forma e sim de modo satisfatório, pois, quando não o é, a sociedade fica sujeita a diversos tipos de violência”; nesse segmento do texto, o pronome “o” sublinhado substitui um termo anterior, que é:','{"A": "o mesmo.", "B": "executado de qualquer forma.", "C": "executado de modo satisfatório.", "D": "importância constitucional."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',6,'Língua Portuguesa',null,'Algumas palavras presentes no texto foram selecionadas abaixo. Assinale a opção que mostra um sinônimo adequado para a palavra selecionada.','{"A": "atividade / profissão.", "B": "comunidade / vizinhança.", "C": "sociedade / população.", "D": "agressividade / marginalidade."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',7,'Língua Portuguesa',null,'Assinale a frase opinativa sobre o texto que está construída com sentido figurado.','{"A": "O texto é claro como água.", "B": "O texto mostra opiniões seguras.", "C": "O texto é curto, mas preciso.", "D": "O texto traz informações de valor."}'::jsonb,'A',true,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',8,'Língua Portuguesa',null,'Todas as frases abaixo iniciam um texto; assinale aquela que mostra marcas de um texto literário.','{"A": "Diariamente o batalhão policial inicia seu trabalho cedo.", "B": "Todos os dias ele acordava e preparava-se para trabalhar.", "C": "Os quartéis militares têm atividade constante.", "D": "Os serviços de segurança são indispensáveis."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',9,'Língua Portuguesa',null,'Em todas as frases abaixo está presente a palavra segurança; assinale aquela frase em que o significado da palavra é diferente do de todas as demais frases.','{"A": "O serviço de segurança do shopping é muito eficiente.", "B": "Os guardas respondem às perguntas com segurança.", "C": "Há muitos dispositivos eletrônicos na segurança das casas.", "D": "A polícia se encarrega da segurança do bairro."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',10,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','O texto é um resumo de um trabalho escrito sobre a segurança pública no Brasil. Nesse resumo há críticas a vários aspectos dos serviços de segurança. Assinale a opção que mostra uma crítica que não está referida no texto.','{"A": "A impunidade presente em muitos casos.", "B": "Falhas na política brasileira que prejudicam a segurança.", "C": "A violência reiterada de alguns agentes criminosos.", "D": "O trabalho mal remunerado da polícia."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',11,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','“Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública brasileira, enfatizando suas falhas.” Esse primeiro período do texto tem a finalidade principal de','{"A": "mostrar o cuidado tomado com a análise feita.", "B": "indicar que se trata de um estudo feito por cientistas.", "C": "destacar o conteúdo abordado no trabalho.", "D": "demonstrar tratar-se de uma análise imparcial dos fatos."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',12,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','“Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões.” Entre os termos sublinhados no fragmento textual acima, assinale aquele que foi substituído de forma inadequada.','{"A": "do Brasil / brasileira.", "B": "de impunidade / impune.", "C": "da polícia / policial.", "D": "das prisões / carcerário."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',13,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','“Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas.” Nesse período do texto, o pronome demonstrativo “esse” pode ser substituído por “este”, mesmo não sendo obrigatória a substituição. Assinale a frase abaixo em que o demonstrativo “esse” deve ser obrigatoriamente substituído por “este”.','{"A": "Li em “Ressurreição”, de Machado de Assis, passagens brilhantes, apesar de não ser esse o melhor romance dele.", "B": "Comprei um vinho chileno e um argentino, mas entre esse e aquele não sei qual o melhor.", "C": "Esse livro que o conferencista citou merece ser comprado.", "D": "Deixe na varanda esse guarda-chuva que você tem na mão direita."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',14,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','No texto há um erro gramatical. Assinale a opção que identifica corretamente esse erro.','{"A": "A frase iniciada pela forma de gerúndio “Sendo” deveria ser precedida de vírgula e não separada por ponto.", "B": "A preposição “sobre” na primeira linha do texto deveria ser substituída por “sob”.", "C": "A forma de gerúndio “enfatizando” deveria, por clareza, ser substituída por “com ênfase nas”.", "D": "A expressão “bem como” perderia a ambiguidade se fosse substituída por “assim como”."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',15,'Língua Portuguesa','Problemas da segurança pública “Esse trabalho científico se destina a realizar uma análise sobre a situação da segurança pública do Brasil, enfatizando suas falhas. Sendo abordada a violência que assola o meio social, bem como o sentimento de impunidade. Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” (Jus.com.br / 28-07-2015)','A seguinte palavra empregada no texto mostra duplicidade de formas gráficas igualmente corretas:','{"A": "análise / análize.", "B": "enfatizando / enfatisando.", "C": "aspecto / aspeto.", "D": "assola / açola."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',16,'Língua Portuguesa',null,'Assinale a frase abaixo que mostra erro de concordância verbal.','{"A": "Chegou um milhão de revólveres para a polícia.", "B": "Veio presa uma quadrilha de assaltantes de bancos.", "C": "O policial e o assaltante se enfrentou durante o assalto.", "D": "As vítimas identificaram as fotos dos criminosos."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',17,'Língua Portuguesa',null,'A regência é um dos tópicos dos conteúdos desta prova; assinale a frase abaixo que mostra regência gramaticalmente correta.','{"A": "O criminoso esqueceu da arma na cena do crime.", "B": "O prisioneiro namorou com a advogada por dois anos.", "C": "O prefeito entregou o prêmio os melhores policiais.", "D": "A prisão implica a aplicação de uma pena."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',18,'Língua Portuguesa','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.”','Assinale a opção que mostra vocábulos que são acentuados em função da mesma regra de acentuação gráfica.','{"A": "público / política.", "B": "polícia / será.", "C": "além / réus.", "D": "é / à."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',19,'Língua Portuguesa','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.”','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.” Assinale a opção que apresenta corretamente o sentido de uma dessas palavras ou expressões do texto.','{"A": "Dessa forma / modo.", "B": "como / comparação.", "C": "além disso / lugar.", "D": "mais / quantidade."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',20,'Língua Portuguesa','“Dessa forma, são apresentados os aspectos que envolvem esse serviço público, como o trabalho da polícia e o sistema das prisões. Além disso, é evidenciada a política brasileira que se torna um empecilho à garantia de uma sociedade mais segura. É importante ressaltar que nesse trabalho será evidenciada a violência que tem como praticantes agentes que delinquem reiteradamente e que são réus de diversos processos penais.”','Nas opções abaixo, há duas palavras presentes no texto; assinale a opção em que a troca de posição dessas palavras altera o seu sentido original.','{"A": "trabalho científico / científico trabalho.", "B": "sociedade mais segura / mais segura sociedade.", "C": "será evidenciada a violência / será a violência evidenciada.", "D": "diversos processos penais / processos penais diversos. Raciocínio Lógico"}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',21,'Raciocínio Lógico',null,'Em grupo de desportistas, todos os ciclistas jogam futebol e alguns ciclistas jogam basquete. Com respeito aos indivíduos desse grupo, pode-se afirmar que','{"A": "todos aqueles que jogam futebol também são ciclistas.", "B": "todos aqueles que jogam basquete também são ciclistas.", "C": "quem não joga futebol não é ciclista.", "D": "quem é ciclista joga basquete."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',22,'Raciocínio Lógico',null,'Considere a seguinte afirmação: “Se todos os cidadãos contribuem, então o país melhora” Ela apresenta a estrutura lógica 𝑝→𝑞. Tal afirmação é logicamente equivalente a','{"A": "“Se nenhum cidadão contribui, então o país piora”.", "B": "“Se o país não melhora, então nem todo cidadão contribui’.", "C": "“Se algum cidadão não contribui, então o país não melhora”.", "D": "“Se o país piora, então algum cidadão não contribui”."}'::jsonb,'B',true,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','fórmulas, frações ou expoentes podem ter sido distorcidos na extração do PDF; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',23,'Raciocínio Lógico',null,'As figuras abaixo ilustram as 3 primeiras etapas da sucessiva transformação de um polígono em outro. Essa modificação é feita removendo-se todos os “bicos” do polígono anterior para obter- se o polígono seguinte. Etapa 1 Etapa 2 Etapa 3 A figura obtida na Etapa 4 será um polígono com','{"A": "16 lados.", "B": "20 lados.", "C": "24 lados.", "D": "36 lados."}'::jsonb,'C',true,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',24,'Raciocínio Lógico',null,'Em um conjunto de 20 objetos, 12 têm a característica A e 9 têm a característica B. Apenas 3 dos objetos não possuem nem a característica A, nem a característica B. Assim, a quantidade de objetos desse conjunto que possuem simultaneamente as características A e B é igual a','{"A": "1.", "B": "2.", "C": "3.", "D": "4."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',25,'Raciocínio Lógico',null,'Em uma caixa, há 2 bolas brancas e 3 bolas pretas. De forma totalmente aleatória, Almir sorteará uma bola por vez dessa caixa, sem que nunca sejam repostas, encerrando as extrações assim que, entre as sorteadas, houver pelo menos uma de cada cor. O número máximo de bolas que Almir pode sortear é igual a','{"A": "2.", "B": "3.", "C": "4.", "D": "5."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',26,'Raciocínio Lógico',null,'Pereira, Rodrigues, Santos e Tavares são soldados que disputam uma corrida. Em certo momento da competição, as suas posições são tais que: - se Tavares ultrapassar 2 soldados, passará a ser o 1º colocado; - Pereira não é o último colocado; - Santos não pode ultrapassar ninguém. Se apenas essas quatro pessoas estão disputando a corrida, conclui-se que','{"A": "Santos está em primeiro e Rodrigues está em terceiro.", "B": "Pereira está em primeiro e Tavares está em terceiro.", "C": "Pereira está em segundo e Rodrigues está em quarto.", "D": "Rodrigues está em segundo e Tavares está em terceiro."}'::jsonb,'C',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',27,'Raciocínio Lógico',null,'Um soldado iniciou um treinamento para uma prova de flexão de braço fazendo, no primeiro dia, um total de 6 repetições da seguinte forma: - 1 repetição na 1ª série; - 2 repetições na 2ª série; e - 3 repetições na 3ª série. No segundo dia, o soldado fez um total de 10 repetições da seguinte forma: - 1 repetição na 1ª série; - 2 repetições na 2ª série; - 3 repetições na 3ª série; e - 4 repetições na 4ª série. E assim, a cada dia, o soldado acrescentou uma série a mais ao treino do dia anterior com uma repetição a mais, de modo que a nª série tem n repetições. Mantendo o padrão, o soldado deverá fazer, no 8º dia de treinamento, um total de','{"A": "55 repetições.", "B": "66 repetições.", "C": "78 repetições.", "D": "91 repetições."}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',28,'Raciocínio Lógico',null,'São logicamente verdadeiras as seguintes afirmações: I. Eu sou casado ou eu não sou policial. II. Eu não tenho filho e eu não sou casado. A partir dessas informações, pode-se afirmar que','{"A": "eu não sou casado, sou policial e não tenho filho.", "B": "eu não sou casado, não sou policial e não tenho filho.", "C": "eu sou casado, sou policial e tenho filho.", "D": "eu sou casado, não sou policial e tenho filho."}'::jsonb,'B',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',29,'Raciocínio Lógico',null,'Considere a seguinte afirmação: “Todas as pessoas apreendidas têm 21 anos ou mais e são do sexo masculino” A negação dessa afirmação é:','{"A": "Nenhuma pessoa apreendida tem 21 anos ou mais ou é do sexo masculino.", "B": "Nenhuma pessoa apreendida tem 21 anos ou mais e é do sexo masculino.", "C": "Pelo menos uma das pessoas apreendidas tem menos de 21 anos e é do sexo feminino.", "D": "Pelo menos uma das pessoas apreendidas tem menos de 21 anos ou é do sexo feminino."}'::jsonb,'D',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',30,'Raciocínio Lógico',null,'Uma sequência de números inteiros foi criada escolhendo-se os dois primeiros termos e, a partir do 3º termo, os próximos números da sequência foram calculados por meio de uma mesma operação básica envolvendo os dois antecessores imediatos. A seguir, são apresentados os seis primeiros termos dessa sequência numérica. 2, -1, 1, 0, 1, 1, ... Seguindo esse padrão de construção, o valor do próximo termo é','{"A": "2.", "B": "1.", "C": "0.", "D": "-1. Conhecimentos Específicos"}'::jsonb,'A',false,false,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',31,'Direito Penal',null,'Suponha que, no interior de uma aeronave privada brasileira a serviço do governo brasileiro, foi cometido um delito de furto quando tal aeronave estava localizada em aeroporto de país estrangeiro. Nesse caso, de acordo com o Código Penal brasileiro, é correto afirmar que','{"A": "pelo princípio da territorialidade, deverá ser aplicada apenas a lei penal estrangeira, uma vez que se trata de aeronave privada, ainda que a serviço do governo brasileiro, que se encontrava em território estrangeiro no momento em que o delito foi cometido.", "B": "poderá ser aplicada a lei penal brasileira, por serem consideradas como extensão do território nacional as aeronaves brasileiras, ainda que privadas, a serviço do governo brasileiro, onde quer que se encontrem.", "C": "pelo princípio da extraterritorialidade da lei penal brasileira, esta poderá ser aplicada ao delito cometido no interior de aeronave privada brasileira a serviço do governo brasileiro, desde que haja requerimento do Ministro da Justiça às autoridades estrangeiras do país onde o delito foi cometido.", "D": "pelo princípio da extraterritorialidade da lei penal brasileira, esta poderá ser aplicada ao delito cometido no interior de aeronave privada brasileira a serviço do governo brasileiro, desde que haja requerimento do Ministro das Relações Exteriores às autoridades estrangeiras do país onde o delito foi cometido."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',32,'Direito Penal',null,'Sobre as excludentes de ilicitude reconhecidas pelo Direito Penal Brasileiro, é correto afirmar que','{"A": "a legítima defesa, o estado de necessidade, o estrito cumprimento de dever legal, o exercício regular de direito e o consentimento do ofendido são excludentes que, expressamente, encontram-se previstas no Código Penal.", "B": "dentre todas as excludentes de ilicitude, o excesso punível somente é previsto para a legítima defesa.", "C": "não pode alegar estado de necessidade quem tinha o dever legal de enfrentar o perigo.", "D": "configura-se a legítima defesa quando o agente, usando moderadamente dos meios necessários, repele injusta agressão, atual ou iminente, a direito próprio. Quando visa a repelir injusta agressão a terceiros, age-se em estado de necessidade."}'::jsonb,'C',true,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',33,'Direito Penal',null,'Paulo, pai de Joaquim e Ana, todas as vezes em que tem ciência de que sua filha chegou em casa após as 22h, a agride fisicamente. O mesmo não ocorre em relação ao seu filho, com quem é sempre mais compreensivo. Certo dia, Paulo extrapola nas agressões físicas e mata Ana. Cumpre destacar que Paulo não reside no mesmo local que seus filhos já que, desde pequenos, moram com a avó materna. Sobre a situação narrada, é correto afirmar que','{"A": "Paulo cometeu homicídio qualificado contra sua filha Ana, na modalidade feminicídio.", "B": "Paulo cometeu homicídio qualificado por motivo fútil, não sendo possível a tipificação da conduta por feminicídio, em razão de não ter sido cometido no âmbito da violência doméstica, já que o agente não residia com a vítima.", "C": "No caso mencionado, somente seria possível a tipificação da conduta como feminicídio caso a vítima tivesse relação afetiva com o agente, como namoro ou união estável.", "D": "Nos termos do Código Penal, para a configuração do feminicídio, basta a constatação de o agente ser homem e a vítima ser mulher."}'::jsonb,'A',true,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',34,'Legislação Especial e Direitos Humanos',null,'Acerca da Declaração Universal dos Direitos Humanos (ONU, 1948), analise as afirmativas a seguir e assinale (V) para a verdadeira e (F) para a falsa. ( ) O casamento não será válido senão com o livre e pleno consentimento dos nubentes, vedando-se a prática da poligamia. ( ) Ninguém poderá ser culpado por qualquer ação ou omissão que, no momento, não constituíam delito perante o direito nacional ou internacional. Também não será imposta pena mais forte do que aquela que, no momento da prática, era aplicável ao ato delituoso. ( ) Todo ser humano, vítima de perseguição, tem o direito de procurar e de gozar asilo em outros países, salvo em caso de perseguição legitimamente motivada por crimes de direito comum ou por atos contrários aos objetivos e princípios das Nações Unidas. As afirmativas são, respectivamente,','{"A": "V - V - V.", "B": "F - V - V.", "C": "V - F - F.", "D": "F - V - F."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',35,'Legislação Especial e Direitos Humanos',null,'Acerca dos crimes de preconceito de raça ou de cor, previstos na Lei nº 7.716/89, é correto afirmar que','{"A": "se o crime de induzir preconceito de raça for cometido pelos meios de comunicação social, uma medida possível de combate ao preconceito é a interdição das respectivas mensagens na rede mundial de computadores.", "B": "serão punidos, na forma da Lei nº 7.716/89, os crimes resultantes de discriminação ou preconceito de raça, cor ou etnia. Os crimes resultantes de preconceito de religião ou procedência nacional não são abarcados pela referida lei.", "C": "constitui efeito automático da condenação a perda do cargo ou função pública, para o servidor público, e a suspensão do funcionamento do estabelecimento particular por prazo não superior a três meses.", "D": "a conduta de veicular símbolos que utilizem a cruz suástica, para fins de divulgação do nazismo, não constitui crime, em razão do direito fundamental à liberdade de expressão."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',36,'Legislação Especial e Direitos Humanos',null,'Nos termos da Lei nº 9.455/97, que define os crimes de tortura, quando um agente policial submete alguém, sob sua guarda, poder ou autoridade, com emprego de violência ou grave ameaça, a intenso sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida de caráter preventivo, é possível afirmar que','{"A": "não há previsão legal de punição penal para aquele que se omite em face dessas condutas, quando tinha o dever de evitá-las ou apurá-las.", "B": "o crime de tortura é inafiançável e insuscetível de graça, cabendo, contudo, o benefício da anistia em situações excepcionais.", "C": "a condenação acarretará a perda do cargo, função ou emprego público e a interdição para seu exercício pelo dobro do prazo da pena aplicada.", "D": "sendo o crime cometido por agente policial, aumenta-se a pena de um terço até metade."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',37,'Legislação Especial e Direitos Humanos',null,'Nos termos do Estatuto da Criança e do Adolescente – Lei nº 8.069/90, é correto afirmar que','{"A": "um adolescente de 14 (quatorze) anos que pratica vias de fato contra alguém, conduta tipificada na Lei de Contravenções Penais, não comete ato infracional.", "B": "são penalmente inimputáveis os menores de dezoito anos, sujeitos às medidas previstas nesta Lei, salvo quando emancipados, a partir de dezesseis anos, passando a adquirir imputabilidade criminal.", "C": "é vedada a internação do adolescente antes do trânsito em julgado da sentença.", "D": "o adolescente civilmente identificado não será submetido à identificação compulsória pelos órgãos policiais, de proteção e judiciais, salvo para efeito de confrontação, havendo dúvida fundada."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',38,'Direito Processual Penal',null,'José foi preso por agente policial em flagrante delito, no instante em que cometia a infração penal. Nesse caso, é correto afirmar que','{"A": "caso José fosse encontrado, logo depois, com instrumentos que fizessem presumir ser ele autor da infração, ainda assim, não haveria possibilidade de sua prisão em flagrante delito.", "B": "nos termos do Código de Processo Penal, o flagrante delito somente é verificado quando o agente está cometendo a infração penal ou acabou de cometê-la.", "C": "em razão de ter sido preso em flagrante delito, não é permitido a José prestar fiança em qualquer circunstância.", "D": "caso haja falta de testemunhas da infração, tal fato não impedirá o auto de prisão em flagrante; mas, nesse caso, com o condutor, deverão assiná-lo pelo menos duas pessoas que hajam testemunhado a apresentação do preso à autoridade."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',39,'Legislação Especial e Direitos Humanos',null,'Acerca da Lei nº 13.869/19, que dispõe sobre os crimes de abuso de autoridade, é correto afirmar que','{"A": "constitui crime de abuso de autoridade constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo.", "B": "não constitui crime de abuso de autoridade decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais, pois, para tal situação, existe a possibilidade de relaxamento da prisão ilegal.", "C": "somente servidores públicos, no exercício de suas funções ou a pretexto de exercê-las, podem ser agentes dos delitos previstos na referida lei.", "D": "deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão não constitui crime de abuso de autoridade, pois visa a resguardar a integridade do agente policial."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',40,'Direito Penal',null,'José foi flagrado pela autoridade policial cometendo crime de menor potencial ofensivo. Nessa hipótese, nos termos da Lei nº 9.099/95, é correto afirmar que','{"A": "ao autor do fato que, após a lavratura do termo, for imediatamente encaminhado ao Juizado ou assumir o compromisso de a ele comparecer, se imporá prisão em flagrante.", "B": "a soltura do preso em flagrante delito por crime de menor potencial ofensivo somente será possível mediante a prestação de fiança.", "C": "a autoridade policial que tomar conhecimento da ocorrência lavrará termo circunstanciado e o encaminhará imediatamente ao Juizado, com o autor do fato e a vítima, providenciando-se as requisições dos exames periciais necessários.", "D": "em caso de violência doméstica, o juiz não poderá determinar, antes do trânsito em julgado da sentença, seu afastamento do lar, domicílio ou local de convivência com a vítima."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',41,'Direito Penal Militar',null,'Acerca das disposições contidas no Código Penal Militar, julgue os itens a seguir: I. É punível com pena de detenção a conduta de embriagar-se o militar, quando em serviço, ou apresentar-se embriagado para prestá-lo. II. É punível com detenção a conduta de dormir o militar, quando em serviço, como oficial de quarto ou de ronda, ou em situação equivalente, ou, não sendo oficial, em serviço de sentinela, vigia, plantão às máquinas, ao leme, de ronda ou em qualquer serviço de natureza semelhante. III. É punível com reclusão desacatar superior, ofendendo-lhe a dignidade ou o decoro, ou procurando deprimir-lhe a autoridade. Está correto o que se afirma em','{"A": "I e II, apenas.", "B": "II e III, apenas.", "C": "I e III, apenas.", "D": "I, II e III."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',42,'Direito Constitucional',null,'Assinale a opção que representa um direito ou garantia individual previsto expressamente no Art. 5º da Constituição Federal de 1988.','{"A": "Todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, desde que não frustrem outra reunião anteriormente convocada para o mesmo local, sendo exigida autorização prévia da autoridade competente.", "B": "A casa é asilo inviolável do indivíduo, ninguém nela podendo penetrar sem consentimento do morador, salvo em caso de flagrante delito ou desastre, ou para prestar socorro, ou, durante o dia, por determinação judicial.", "C": "A prática do racismo constitui crime inafiançável, porém prescritível em 15 (quinze) anos, sujeito à pena de reclusão, nos termos da lei.", "D": "Não haverá pena de morte, mesmo em caso de guerra declarada."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',43,'Direito Processual Penal',null,'Acerca das disposições previstas no Código de Processo Penal Militar, é correto afirmar que','{"A": "o inquérito policial militar é a apuração sumária de fato, que, nos termos legais, configure crime militar e de sua autoria, tendo caráter de instrução definitiva.", "B": "nas infrações permanentes, considera-se o agente em flagrante delito enquanto não cessar a permanência.", "C": "é definitiva a prisão que ocorre durante o inquérito, ou no curso do processo, ainda que antes da condenação.", "D": "somente os militares poderão prender quem for insubmisso ou desertor."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',44,'Legislação de Trânsito',null,'Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência é conduta prevista no Código de Trânsito Brasileiro (CTB). Sobre o tema, é correto afirmar que','{"A": "a conduta descrita somente será crime previsto no CTB se for constatada concentração igual ou superior a 6 decigramas de álcool por litro de sangue ou igual ou superior a 0,3 miligrama de álcool por litro de ar alveolar.", "B": "a conduta descrita será crime e infração administrativa previstos no CTB qualquer que seja a concentração de álcool por litro de sangue ou por litro de ar alveolar.", "C": "em se tratando de conduta criminosa, a capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência somente poderá ser obtida mediante teste de alcoolemia ou toxicológico ou exame clínico.", "D": "a conduta descrita somente será infração administrativa prevista no CTB se for constatada concentração igual ou superior a 9 decigramas de álcool por litro de sangue ou igual ou superior a 0,6 miligrama de álcool por litro de ar alveolar."}'::jsonb,'X',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',45,'Legislação Especial e Direitos Humanos',null,'A violência doméstica contra a mulher, infelizmente, é uma realidade que, todos os dias, aterroriza milhares de brasileiras. Muitas mulheres não são capazes de se libertar dessa situação por medo ou dependência emocional e econômica dos parceiros. Sobre esse tema, de acordo com a Lei Maria da Penha – Lei nº 11.340/06, é correto afirmar que','{"A": "embora existam outras formas de violência doméstica contra a mulher, a Lei Maria da Penha somente menciona expressamente a violência física e sexual.", "B": "é direito da mulher em situação de violência doméstica e familiar o atendimento policial e pericial especializado, ininterrupto e prestado por servidores - preferencialmente do sexo feminino - previamente capacitados.", "C": "a inquirição de mulher em situação de violência doméstica, quando se tratar de crime contra a mulher, obedecerá, dentre outras, à diretriz de garantir o contato direto da mulher, seus familiares e testemunhas com o investigado para fins de acareação.", "D": "verificada a existência de risco atual à vida da mulher em situação de violência doméstica, o agressor somente poderá ser afastado do lar, em qualquer hipótese, por ordem judicial."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',46,'Legislação Institucional (PM-SP)',null,'Acerca da Lei Complementar nº 893/01, do Estado de São Paulo, que institui o Regulamento Disciplinar da Polícia Militar, é correto afirmar que','{"A": "transgressão disciplinar é a infração criminal caracterizada pela violação dos deveres policiais-militares, cominando ao infrator as sanções previstas no Código Penal Militar.", "B": "as transgressões disciplinares são classificadas de acordo com sua gravidade em graves (G), médias (M) e leves (L).", "C": "não constitui transgressão disciplinar dormir em serviço de policiamento, vigilância ou segurança de pessoas ou instalações, desde que haja mais de um policial no local.", "D": "as sanções disciplinares aplicáveis aos militares do Estado, independentemente do posto, graduação ou função que ocupem, são detenção, demissão e expulsão, apenas."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',47,'Legislação Institucional (PM-SP)',null,'De acordo com as I-21-PM, Instruções para continências, honras, sinais de respeito e cerimonial militar na Polícia Militar, assinale a afirmativa incorreta.','{"A": "Para falar, formalmente, ao Comandante Geral, o tratamento é \"Vossa Excelência\".", "B": "O Secretário da Segurança Pública do Estado do Paraná, quando em visita de caráter oficial ao Estado de São Paulo, tem direito à continência.", "C": "O Teto de Honra, para as praças da ativa, da reserva ou reformados, consiste em homenagens aos nubentes, a fim de dar boas-vindas à família policial-militar por conta das cerimônias de enlace matrimonial.", "D": "Na continência da guarda, o comandante da guarda comandará: “APRESENTAR-ARMA!, OLHAR À ESQUERDA!” caso a autoridade visitante seja o Comandante-Geral da PM."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',48,'Legislação Institucional (PM-SP)',null,'O uniforme é o símbolo da autoridade e seu uso correto é fator primordial na apresentação individual e coletiva do policial militar, contribuindo para o fortalecimento da disciplina e para a boa imagem da Instituição. De acordo com os Regulamentos de Uniformes da Polícia Militar - R-5-PM, é correto afirmar que','{"A": "os uniformes da Polícia Militar classificam-se em três categorias apenas: formais, operacionais básicos e específicos.", "B": "a posse do uniforme SM-1 [Social (Passeio Completo) Masculino - 1] será obrigatória para os Oficiais e facultada para as Praças.", "C": "a posse do uniforme GM-1 (Gala Masculino – 1) será obrigatória para Subcomandante da Polícia Militar (Subcmt PM) e Praças.", "D": "a posse do uniforme PM-1 (Passeio Masculino - 1) será obrigatória para os Oficiais e Praças."}'::jsonb,'B',true,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',49,'Legislação Especial e Direitos Humanos',null,'José foi flagrado por agente policial consumindo cigarro de maconha. No mesmo local, foram identificadas duas mudas plantadas de cannabis sativa com o fim de confecção de cigarros de maconha apenas para consumo próprio recreativo de José. De acordo com a Lei nº 11.343/06, que institui o Sistema Nacional de Políticas Públicas sobre Drogas – Sisnad, é correto afirmar que','{"A": "o consumo e plantio de maconha para uso próprio e com fins recreativos não são mais considerados crimes no ordenamento jurídico brasileiro.", "B": "o consumo de maconha para uso próprio e com fins recreativos não é mais considerado crime no ordenamento jurídico brasileiro, mas seu plantio, ainda que para consumo próprio e com fins recreativos, permanece criminalizado.", "C": "o consumo e plantio de maconha para uso próprio e com fins recreativos são crimes puníveis com pena de detenção, de seis meses a um ano, e multa.", "D": "o consumo e plantio de maconha para uso próprio e com fins recreativos são crimes, embora não sejam mais puníveis com pena privativa de liberdade."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',50,'Legislação Especial e Direitos Humanos',null,'Paulo, cidadão que possui registro regular de posse de arma, foi flagrado na via pública por agente policial portando arma de fogo desmuniciada, de uso permitido e devidamente registrada em seu nome, quando se dirigia de sua casa para seu escritório. Nesse caso, sobre a possibilidade de transitar com sua arma nas ruas, é correto afirmar que','{"A": "a posse regular de arma de fogo presume a autorização para porte de trânsito em todo território nacional.", "B": "a posse regular de arma de fogo não presume a autorização para porte de arma de fogo, que deve ser concedida pela Polícia Federal.", "C": "a concessão de autorização para porte de arma de fogo é de competência da Polícia Civil do Estado em que o certificado de posse foi expedido.", "D": "a autorização para porte de trânsito de arma de fogo deverá possuir eficácia territorial e temporal ilimitada."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',51,'Legislação Institucional (PM-SP)',null,'De acordo com as Instruções para Afastamentos na Polícia Militar do Estado de São Paulo – I-36-PM, é correto afirmar que','{"A": "a licença-adoção não é reconhecida de forma expressa na I- 36-PM.", "B": "todo policial militar terá direito a usufruir 5 (cinco) dias de licença-paternidade quando ocorrer o nascimento (com vida) de seu filho. Na ocorrência do nascimento de mais de um filho na mesma data, será concedida licença de 10 (dez) dias.", "C": "todo policial militar terá direito a período de luto de 2 (dois) dias em caso de falecimento de neto.", "D": "toda policial militar terá direito a usufruir 160 (cento e sessenta) dias de licença-gestante, a qual, mediante prescrição médica, poderá ser iniciada a partir da 34ª (trigésima quarta) semana de gestação."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',52,'Legislação Institucional (PM-SP)',null,'Acerca dos conceitos presentes na Nota de Instrução PM3-1/02/15 - Sistemática de Atuação da Polícia Militar no Atendimento e Registro de Ocorrências - Resolução SSP-57/2015 -, julgue as afirmativas a seguir. I. O “atendimento preferencial” consiste em atender a unidade de serviço em serviço, quando da apresentação de ocorrência criminal em unidade da Polícia Civil (Delegacia ou Distrito Policial), com a celeridade possível, visando a seu retorno às atividades de polícia ostensivo-preventiva, respeitados os critérios de prioridade de atendimento estabelecidos na Constituição Federal e legislação infraconstitucional. II. A “comunicação” consiste em cientificar o Delegado de Polícia acerca de ocorrência criminal atendida pela Polícia Militar. III. A “Notificação de Ocorrência - NOc” consiste em formulário sumário elaborado pelas unidades de serviço, no próprio local de atendimento, com dados básicos sobre a ocorrência e a qualificação dos policiais militares responsáveis pelo atendimento e das partes envolvidas. Está correto o que se afirma em','{"A": "I e II, apenas.", "B": "I e III, apenas.", "C": "II e III, apenas.", "D": "I, II e III."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',53,'Legislação Institucional (PM-SP)',null,'De acordo com a Portaria do Cmt G CORREGPM-1/360/13, que regulamenta o procedimento disciplinar, é correto afirmar que','{"A": "vislumbrado o cometimento de transgressão disciplinar, a autoridade competente, instaurará o Procedimento Disciplinar, com a sua autuação e a elaboração do Termo Acusatório, motivado com as razões de fato e de direito, para que o acusado possa exercitar o seu direito à ampla defesa e ao contraditório.", "B": "ao receber a comunicação disciplinar, a autoridade competente analisará os fatos, no prazo de 5 (cinco) dias e, caso vislumbre que ela não preenche os requisitos suficientes para a formulação de Termo Acusatório, poderá apenas arquivá-la.", "C": "para se evitar constrangimentos entre as partes, não será admitida acareação entre acusados, entre acusado e testemunha, entre testemunhas, entre acusado ou testemunha e a pessoa ofendida, e entre as pessoas ofendidas, mesmo se divergirem, em suas declarações, sobre fatos ou circunstâncias relevantes.", "D": "a falta de defesa técnica por advogado ofende os direitos constitucionais de ampla defesa e contraditório do acusado, importando a remarcação da audiência de instrução e julgamento."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',54,'Legislação Institucional (PM-SP)',null,'De acordo com a Diretriz PM3-1/02/20, que estabelece Normas para o Sistema Operacional de Policiamento PM – NORSOP, é correto afirmar que','{"A": "o único objetivo expressamente mencionado na Diretriz PM3-1/02/20 é padronizar a sistemática de emprego operacional.", "B": "para alicerçar as práticas organizacionais, destacam-se os seguintes princípios básicos: Polícia Comunitária, Direitos Humanos e Excelência da gestão.", "C": "o Sistema Operacional de Policiamento PM baseia-se, exclusivamente, na Matriz Operacional do Policiamento Preventivo.", "D": "o Programa de Radiopatrulha está inserido nos Programas de Policiamento Complementares, enquanto o Programa de Policiamento Escolar está inserido nos Programas de Policiamento Primários."}'::jsonb,'B',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',55,'Legislação Institucional (PM-SP)',null,'Em uma abordagem policial com viatura “4 rodas”, a equipe de policiais, composta por 2 (dois) integrantes, se deparou com pessoas em atitude sob fundada suspeita. Nesse caso, de acordo com o “Procedimento Operacional Padrão – processo 1.02.00 – Abordagem Policial com viatura 4 rodas”, é correto afirmar que','{"A": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado e as armas no coldre.", "B": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado e as armas na posição “3º Olho”.", "C": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado e as armas na posição “Sul”.", "D": "os policiais se posicionarão de maneira “semidesembarcada”, com as portas da viatura abertas, o motor ligado, estando um deles com a arma na posição “3º Olho” e o outro com a arma no coldre."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',56,'Legislação Institucional (PM-SP)',null,'De acordo com a Ordem de Serviço PM3-11/02/18-CIRCULAR, que dispôs sobre o uso de dispositivos luminosos (faróis/giroflex) e/ou sonoros (sirenes/buzinas) pelas viaturas, é correto afirmar que','{"A": "o uso do dispositivo luminoso de emergência (giroflex) deverá ocorrer, durante o dia e a noite, em todos os deslocamentos e estacionamentos preventivos.", "B": "o uso de sirenes será obrigatório, durante o dia ou à noite, nos deslocamentos para atendimento de ocorrências, desde que caracterizada a condição de emergência.", "C": "todas as viaturas caracterizadas da Instituição, nos seus deslocamentos, deverão trafegar com os faróis baixos (luzes baixas) ligados após as 18h.", "D": "as viaturas, mesmo em situações de emergência, não poderão utilizar os faróis altos."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',57,'Legislação Institucional (PM-SP)',null,'De acordo com a Diretriz PM3-5/02/20 – Programa de Policiamento Comunitário, “a atuação direcionada a localidades específicas, estabelecidas conforme critérios estratégicos, visando alcançar níveis aceitáveis de segurança pública e qualidade de vida, por meio do respaldo, cooperação, parceria, participação e coleta de informações junto às respectivas comunidades” corresponde ao conceito de','{"A": "policiamento ostensivo comunitário.", "B": "polícia comunitária.", "C": "patrulha comunitária.", "D": "visita comunitária."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',58,'Legislação Institucional (PM-SP)',null,'Há situações que exigem o emprego de efetivo com treinamento tático diferenciado para atuação em ocorrências mais graves, como homicídios, sequestros e roubos. De acordo com a Diretriz PM3-3/02/20 – Programa de Força Tática, assinale a afirmativa incorreta.','{"A": "O Programa FT consiste em Programa de Policiamento Primário, sendo, juntamente com o Programa de Radiopatrulha, prioritário em relação aos demais Programas de Policiamento e Atividades Operacionais Diversas.", "B": "Entre as atividades típicas de apoio tático, menciona-se o controle sobre a criminalidade violenta, mediante a saturação coordenada de áreas de interesse da segurança pública (por exemplo, prevenção a roubos em estabelecimentos bancários, com perímetro de atuação predefinido).", "C": "O Programa de Força Tática tem por objetivo organizar o desenvolvimento do policiamento ostensivo e os apoios táticos executados pelas Forças Táticas.", "D": "O suporte operacional especializado para o atendimento às ocorrências e incidentes graves e/ou passíveis de repercussão, assim classificadas segundo as NORSOP, não é atividade típica de apoio tático."}'::jsonb,'D',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',59,'Legislação Institucional (PM-SP)',null,'A execução de alguns serviços e atividades pode ser delegada, por meio de convênio firmado entre o Estado e os municípios, à Polícia Militar. De acordo com a Diretriz PM3-2/02/14 – Atividade Delegada, é correto afirmar que','{"A": "o efetivo policial-militar designado para a atividade delegada será prioritariamente empregado nas missões definidas como objeto do convênio celebrado com o respectivo município, não podendo ser designado previamente em outras atividades e/ou operações policial-militares ordinárias.", "B": "o policiamento escalado ordinariamente nas mesmas localidades em que atua o efetivo policial-militar designado para a atividade delegada deverá atuar, conjuntamente, nas missões definidas no convênio celebrado.", "C": "a execução da atividade delegada não poderá ser suspensa até o término do convênio.", "D": "o policial militar empregado em atividade delegada estará sujeito à carga horária limite de até 12 (doze) horas diárias e não poderá ultrapassar o teto de 120 (cento e vinte) horas mensais, dentro do mês considerado, independentemente da quantidade de convênios a que se voluntariou."}'::jsonb,'A',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Polícia Militar do Estado de São Paulo','Cabo PM',2022,'2023-03-05','Tipo 1',60,'Direito Penal',null,'Maria, menor de 13 anos de idade, manteve, consensualmente, relação sexual com seu namorado, José, de 18 anos de idade. Nesse caso, de acordo com o Código Penal, é correto afirmar que','{"A": "o consentimento de Maria exclui a ilicitude da conduta de José e, portanto, não há de se falar em crime de estupro de vulnerável.", "B": "a conduta de José somente seria qualificada como crime de estupro de vulnerável caso Maria não tivesse mantido relações sexuais prévias com outra pessoa antes da relação sexual com José.", "C": "José cometeu estupro de vulnerável, independentemente do consentimento da vítima ou de Maria já ter tido relações sexuais prévias com outra pessoa.", "D": "o crime de estupro de vulnerável somente ocorre quando há violência ou grave ameaça contra a vítima."}'::jsonb,'C',false,true,'SP','Polícia Militar','https://conhecimento.fgv.br/sites/default/files/concursos/cabo-pmcnm001-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/pmespcabo2022_gabarito_definitivo.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno')
